-- Pojok Literasi: public slugs + reader-v2 scripts in the table (9 Okt 2026).
-- Paste into the Supabase SQL editor AFTER sql/literasi.sql. Re-pasting is safe.
-- Generated by the app repo's scripts/literasi-v2-sql.js from
-- constants/literasi/v2/*.ts; the app shows slides_v2 when present and the old
-- slides otherwise. A slug is the article's public address
-- (modwizmastery.com/literasi/<slug>); the id stays internal.

alter table literasi_articles add column if not exists slug text;
alter table literasi_articles add column if not exists slides_v2 jsonb;
create unique index if not exists literasi_articles_slug_idx on literasi_articles (slug);

update literasi_articles as a set slug = v.slug, updated_at = now()
