update literasi_articles as a set title = v.title, updated_at = now()
from (values
  ('F-02', $q$Modwiz itu apa, sebenarnya?$q$),
  ('T-01', $q$Peta Modwiz: lima pintu, satu bola$q$),
  ('T-02', $q$Ritual pagi: kenapa penting?$q$),
  ('T-03', $q$Bicara dengan Merlin: kenapa jawabannya bisa mengena$q$),
  ('T-04', $q$Energy dan Souls: kenapa tidak ada angkanya$q$),
  ('T-05', $q$Streak padam? Tidak semuanya hilang$q$),
  ('T-06', $q$Realitas Saya: bergerak, atau cuma sibuk?$q$),
  ('T-07', $q$Mandala: tiga alat, satu urutan$q$),
  ('T-08', $q$Course di HP: kelasmu ikut ke mana saja$q$),
  ('T-09', $q$XP dan Leaderboard: berlomba itu pilihan$q$),
  ('T-10', $q$Kisah: berbagi dalam tiga menit$q$),
  ('J-03', $q$Yakin dan Nyata: dua angka yang jujur$q$),
  ('J-07', $q$Satu malam buruk bukan arah$q$),
  ('J-12', $q$Tiga puluh malam biasa yang menggerakkan posisimu$q$)
) as v(id, title) where a.id = v.id;

update literasi_articles as a set slides_v2 = v.slides::jsonb, updated_at = now()
from (values
  ('T-01', $q${"lead":"Peta Modwiz:","accent":"lima pintu, satu bola","long":false,"slides":[{"kind":"cover","hook":"Aplikasi ini tidak minta dibuka semuanya tiap hari. Kenali lima pintunya sekali, lalu pakai yang kamu butuhkan.","scene":"fiveDoors"},{"kind":"list","head":"Lima pintu","rows":[{"color":"#de4e66","name":"Home","desc":"Ritual harimu dan satu kartu fokus."},{"color":"#f19e3f","name":"Courses","desc":"Kelas yang kamu ikuti."},{"ball":true,"name":"Merlin","desc":"Bola di tengah. Teman bicara yang membaca polamu."},{"color":"#cb3bed","name":"Eksplor Dirimu","desc":"Mandala, sesi, dan Pojok Literasi."},{"color":"#5AC8FA","name":"Profile","desc":"Akses, sertifikat, pengaturan."}]},{"kind":"phone","head":"Yang paling sering kamu buka","text":"Di hari biasa, cukup dua: Home untuk ritual, dan bola Merlin untuk bicara. Pintu lain menunggu sampai kamu membutuhkannya.","pos":"top","screen":"home","callout":{"side":"left","top":0.34,"tag":"Bola di tengah","tagTone":"violet","title":"Merlin","sub":"Bisa diketuk dari layar mana pun."}},{"kind":"quiz","q":"Di hari biasa, dua pintu mana yang paling sering kamu butuhkan?","opts":["Courses dan Profile","Home dan Merlin","Eksplor Dirimu dan Courses"],"ans":1,"exp":"Benar! Home untuk ritual, Merlin untuk bicara. Tapi bagi kamu yang serius mencipta realita, halaman Online Courses adalah tempat sakralmu menguasai realita!"},{"kind":"close","text":"Petanya sudah di tanganmu. Ritual hari ini menunggumu di Home.","cta":"Kembali ke Home","scene":"ritualCard"}]}$q$),
  ('T-02', $q${"lead":"Ritual pagi:","accent":"kenapa penting?","long":false,"slides":[{"kind":"cover","hook":"Ini kesempatan awalmu menciptakan realitamu sendiri, bukan orang lain.","scene":"sunrise"},{"kind":"phone","head":"Mulai dari perasaanmu","text":"Sebelum pesan siapa pun masuk, kenali dulu perasaanmu pagi ini. Satu ketukan, dan harimu dimulai dari dirimu sendiri.","pos":"bottom","screen":"moodpick","callout":{"side":"right","top":0.47,"tag":"Satu ketukan","title":"Pagi ini","visual":"mood"}},{"kind":"phone","head":"Kenapa harus 3 goal?","text":"Karena goal yang terlalu banyak artinya tidak ada fokus yang tepat. Tulis goal harimu yang PALING mendekatkanmu ke target hidupmu!","pos":"top","screen":"goals","callout":{"side":"left","top":0.3,"tag":"Goal 2","title":"Jalan 20 menit sebelum makan siang","visual":"check"}},{"kind":"quiz","q":"Berapa goal yang sebaiknya kamu tulis tiap pagi?","opts":["Tidak perlu ditulis","Lebih dari 3","Maksimal 3"],"ans":2,"exp":"Benar! Goal yang terfokus akan mengarahkan kita lebih dekat dan cepat dengan impian kita."},{"kind":"text","text":"Tidak perlu khawatir jika belum berhasil mencentang goal hari ini. Malam nanti kamu akan melihatnya lagi, dan yang belum tercapai akan menunggumu di pagi berikutnya. Tidak ada yang hilang. Arahmu tetap sama.","scene":"pathDay"},{"kind":"close","text":"Dua menit tiap pagi, dan harimu kamu sendiri yang menentukan.","cta":"Mulai ritual pagi","scene":"morningPhone"}]}$q$),
  ('T-03', $q${"lead":"Bicara dengan Merlin:","accent":"kenapa jawabannya bisa mengena","long":true,"slides":[{"kind":"cover","hook":"Merlin bukan AI biasa. Ia mengenal ritualmu, Mandala-mu, dan realita yang sedang kamu ciptakan.","scene":"orbChat"},{"kind":"list","head":"Bedanya dengan AI lain","text":"AI lain menjawab dari pengetahuan umum. Merlin menjawab dari dirimu.","rows":[{"color":"#f19e3f","glyph":"sun","name":"Membaca ritualmu","desc":"Perasaan dan goal yang kamu isi tiap pagi dan malam ikut dibaca."},{"color":"#7B5CD6","glyph":"rings","name":"Membaca Mandala-mu","desc":"Agni Chakti, Manas, Svadharma. Ke mana kamu condong, Merlin tahu."},{"color":"#de4e66","glyph":"arrow","name":"Mengerti kebutuhanmu","desc":"Jawabannya untuk realita yang sedang kamu ciptakan, bukan jawaban umum."}]},{"kind":"phone","head":"Ceritakan kejadiannya","text":"Bukan kesimpulanmu, melainkan apa yang terjadi. Lalu sebut perasaanmu dengan satu kata. Dua hal ini sudah bahan yang jernih untuk Merlin.","pos":"bottom","screen":"merlin1","callout":{"side":"right","top":0.44,"tag":"Kejadian","tagTone":"violet","title":"+ satu kata perasaan","sub":"\"…tanpa kabar. Aku kesal.\""}},{"kind":"phone","head":"Tanyakan polanya","text":"Daripada \"aku harus apa\", coba \"pola apa yang kamu lihat\". Jawaban yang mengena bisa langsung kamu simpan ke Catatan.","pos":"top","screen":"merlin2","callout":{"side":"left","top":0.3,"tag":"Tahan jawabannya","title":"★ Simpan ke Catatan"}},{"kind":"text","head":"Soal Energy","text":"Ritual harian tidak memakai Energy. Yang memakainya hanya obrolan bebas dengan Merlin.","scene":"energyPaths"},{"kind":"text","text":"Merlin bukan mesin pencari. Ia membaca cerita, perasaan, dan perjalananmu, bukan kata kunci.","scene":"notSearch"},{"kind":"close","text":"Sosok yang paling mengerti realita yang sedang kamu ciptakan.","cta":"Bicara dengan Merlin","scene":"orbChat"}]}$q$),
  ('T-04', $q${"lead":"Energy dan Souls:","accent":"kenapa tidak ada angkanya","long":false,"slides":[{"kind":"cover","hook":"Angka membuatmu berhitung. Bilah membuatmu merasakan: masih cukup, atau sudah tipis.","scene":"barNoNumber"},{"kind":"phone","head":"Bilah, bukan angka kuota","text":"Energy tampil sebagai bilah yang terisi, bukan angka kuota. Ia berkurang tiap kali kamu mengobrol bebas dengan Merlin, dan terisi lagi setiap 16 jam.","pos":"bottom","screen":"energy","callout":{"side":"right","top":0.47,"tag":"Sesi Saat Ini","tagTone":"violet","title":"72% tersisa, bukan angka kuota","visual":"track"}},{"kind":"split","a":"ritual","b":"soul"},{"kind":"quiz","q":"Kegiatan mana yang memakai Energy?","opts":["Ritual harian","Obrolan bebas dengan Merlin","Membaca Pojok Literasi"],"ans":1,"exp":"Benar! Ritual harian selalu gratis. Energy hanya terpakai saat kamu mengobrol bebas dengan Merlin."},{"kind":"split","a":"angka","b":"bilah"},{"kind":"text","text":"Kamu tidak sedang mengelola kuota. Kamu sedang memilih kapan sebuah obrolan layak dilakukan.","scene":"feelBar"},{"kind":"close","text":"Tanpa angka, dan memang sengaja.","cta":"Lihat Energy Merlin di Eksplor Dirimu","scene":"barNoNumber"}]}$q$),
  ('T-05', $q${"lead":"Streak padam?","accent":"Tidak semuanya hilang","long":false,"slides":[{"kind":"cover","hook":"Satu hari terlewat tidak menghapus tiga puluh hari sebelumnya. Streak-mu bisa dinyalakan kembali.","scene":"streakGap"},{"kind":"phone","head":"Jendela tiga hari","text":"Dalam tiga hari setelah padam, streak-mu bisa dinyalakan kembali dengan lima Souls. Pemilik Modwiz Privilege mendapat satu kali gratis setiap bulan.","pos":"bottom","screen":"relight","callout":{"side":"right","top":0.48,"tag":"5 Souls","title":"Nyalakan Kembali","sub":"Privilege: 1× gratis tiap bulan","visual":"mp"}},{"kind":"quiz","q":"Berapa lama waktumu untuk menyalakan kembali streak yang padam?","opts":["Tujuh hari","Satu hari","Tiga hari"],"ans":2,"exp":"Benar! Tiga hari. Dengan lima Souls, atau gratis sekali sebulan untuk Modwiz Privilege."},{"kind":"text","text":"Streak bukan hukuman untuk hari yang gagal. Ia catatan untuk hari-hari yang berhasil. Satu lubang tidak membatalkan seluruh jalannya.","scene":"holeInRow"},{"kind":"close","text":"Tiga puluh hari itu tetap milikmu.","cta":"Buka streak-mu","scene":"streakGap"}]}$q$),
  ('T-06', $q${"lead":"Realitas Saya:","accent":"bergerak, atau cuma sibuk?","long":true,"slides":[{"kind":"cover","hook":"Halaman ini tidak menilai mood-mu. Ia menjawab satu pertanyaan: apakah langkahmu benar-benar mendekatkanmu ke milestone?","scene":"rsGridBig"},{"kind":"phone","head":"Mulai dari milestone-mu","text":"Halaman ini dibuka dengan tujuanmu: milestone, stage, dan sisa waktunya. Semua yang di bawahnya dibaca terhadap itu.","pos":"top","screen":"realitas","callout":{"side":"left","top":0.3,"tag":"Stage 2 dari 3","tagTone":"violet","title":"83 hari lagi"}},{"kind":"text","head":"Tindakan nyata, bukan mood","text":"Angka besarnya adalah langkah yang kamu tulis sendiri di Ritual Malam dan benar-benar kamu kerjakan. Bukan perasaan, bukan nilai. Pola.","scene":"rsHeadlineBig"},{"kind":"phone","head":"Satu kotak, satu malam","text":"Makin pekat ungunya, makin banyak langkah hari itu yang kamu selesaikan. Kotak pucat berarti kamu tidak hadir malam itu. Titik emas: malam berat yang tetap kamu tulis.","pos":"bottom","screen":"realitasGrid","callout":{"side":"right","top":0.47,"tag":"Semua langkah","tagTone":"violet","title":"makin pekat, makin banyak","visual":"swatches"}},{"kind":"text","head":"Yakin dan Nyata","text":"Yakin: apa yang kamu rasakan di dalam. Nyata: apa yang panca indramu lihat di luar. Yang dibaca bukan angkanya, melainkan jaraknya.","scene":"rsBarsBig"},{"kind":"text","head":"Malam yang ditandai","text":"Bintang emas untuk malam berat yang tetap kamu tulis pelajarannya. Bintang ungu untuk malam yang kamu syukuri. Keduanya tinggal di peta ini, bisa kamu baca lagi kapan saja.","scene":"rsMarksBig"},{"kind":"quiz","q":"Apa yang sebenarnya dibaca Realitas Saya?","opts":["Langkah nyata yang benar-benar kamu kerjakan","Nilai dari Merlin","Mood harianmu"],"ans":0,"exp":"Benar! Tindakan nyata dari Ritual Malam. Bukan mood, bukan nilai. Pola."},{"kind":"close","text":"Bergerak, bukan cuma sibuk.","cta":"Buka Realitas Saya","scene":"rsMilestoneBig"}]}$q$),
  ('T-07', $q${"lead":"Mandala:","accent":"tiga alat, satu urutan","long":false,"slides":[{"kind":"cover","hook":"Alat ini tidak menilai siapa kamu selamanya. Ia memotret ke mana kamu condong sekarang.","scene":"threeRings"},{"kind":"phone","head":"Mulai dari Agni Chakti","text":"30 pilihan, sekitar lima menit, lalu Merlin membaca kecenderunganmu. Dari sini, dua alat lainnya jadi lebih bermakna.","pos":"top","screen":"mandala","callout":{"side":"left","top":0.3,"tag":"Mulai di sini","title":"Agni Chakti","sub":"30 pilihan · 5 menit"}},{"kind":"text","head":"Kapan diulang","text":"Agni Chakti: setelah tiga bulan, atau saat target-mu berganti. Manas: kapan saja. Svadharma: setiap ada persimpangan baru dalam hidupmu.","scene":"timeline"},{"kind":"quiz","q":"Alat Mandala mana yang sebaiknya dijalankan pertama?","opts":["Manas","Agni Chakti","Svadharma"],"ans":1,"exp":"Benar! Agni Chakti dulu. Manas bisa kapan saja, Svadharma setiap ada persimpangan."},{"kind":"text","text":"Hasilnya adalah potret, bukan vonis. Karena kamu berubah, potretnya pun diulang.","scene":"snapshot"},{"kind":"close","text":"Potret dirimu hari ini. Mulai dari Agni Chakti.","cta":"Mulai Agni Chakti","scene":"threeRings"}]}$q$),
  ('T-08', $q${"lead":"Course di HP:","accent":"kelasmu ikut ke mana saja","long":false,"slides":[{"kind":"cover","hook":"Kelas yang kamu beli di situs otomatis muncul di sini, tanpa unduh ulang. Belajar jadi bisa di mana saja.","scene":"coursePhone"},{"kind":"phone","head":"Tab Courses","text":"Semua kelasmu ada di sini, dan app mengingat sampai mana kamu menonton. Lanjutkan dari menit terakhir, bukan dari awal.","pos":"bottom","screen":"courses","callout":{"side":"right","top":0.52,"tag":"62%","title":"Lanjut dari menit 7.20"}},{"kind":"phone","head":"Rak Buku dan sertifikat","text":"Modul PDF tersusun rapi di Rak Buku. Sertifikat muncul di Profile begitu kelas tamat.","pos":"top","screen":"rakbuku","callout":{"side":"left","top":0.3,"tag":"Tamat","tagTone":"violet","title":"Sertifikat di Profile"}},{"kind":"quiz","q":"Kelas yang kamu beli di situs, bagaimana cara membukanya di HP?","opts":["Minta tautan lewat email","Unduh ulang dari situs","Otomatis muncul di tab Courses"],"ans":2,"exp":"Benar! Otomatis muncul. Tanpa unduh ulang, tanpa tautan tambahan."},{"kind":"split","a":"sepuluh","b":"nanti"},{"kind":"close","text":"Kelasmu ikut ke mana saja. Sepuluh menit hari ini lebih baik daripada satu jam nanti.","cta":"Buka Courses","scene":"tenMinutes"}]}$q$),
  ('T-09', $q${"lead":"XP dan Leaderboard:","accent":"berlomba itu pilihan","long":false,"slides":[{"kind":"cover","hook":"Kamu tidak harus berlomba. Tetapi kalau mau, aturannya sederhana dan adil.","scene":"podium"},{"kind":"text","head":"Tujuh sumber XP","text":"XP datang dari tujuh kegiatan, termasuk ritual dan check-in. Tiga teratas setiap minggu mendapat Souls.","scene":"podium"},{"kind":"phone","head":"Tombol sembunyi","text":"Kalau papan peringkat tidak cocok untukmu, sembunyikan namamu dengan satu ketukan. XP-mu tetap dihitung.","pos":"top","screen":"leaderboard","callout":{"side":"left","top":0.3,"tag":"Ikon mata","title":"Sembunyikan aku","sub":"XP-mu tetap dihitung."}},{"kind":"quiz","q":"Siapa yang mendapat Souls setiap minggu?","opts":["Tiga teratas","Yang paling banyak berubah","Semua yang punya XP"],"ans":0,"exp":"Benar! Tiga teratas tiap minggu. Dan kalau tidak mau ikut, papannya bisa disembunyikan."},{"kind":"text","text":"Angka di papan tidak mengukur siapa yang paling berubah. Ia mengukur siapa yang paling sering hadir. Dan hadir, memang, sudah separuh pekerjaan.","scene":"halfWork"},{"kind":"close","text":"Berlomba itu pilihan. Hadir adalah separuh pekerjaan.","cta":"Lihat Leaderboard","scene":"podium"}]}$q$),
  ('T-10', $q${"lead":"Kisah:","accent":"berbagi dalam tiga menit","long":false,"slides":[{"kind":"cover","hook":"Perubahan menjadi nyata dua kali: sekali saat terjadi, sekali saat kamu menuliskannya.","scene":"storyCard"},{"kind":"phone","head":"Pintu pertama: akhir pekan","text":"Setiap Sabtu dan Minggu, kartu Ritual Akhir Pekan muncul di Home, tepat di bawah sapaan. Satu ketukan, dan kamu masuk ke Kisah.","pos":"top","screen":"homeKisah","callout":{"side":"right","top":0.44,"tag":"Sabtu & Minggu","title":"Ritual Akhir Pekan","sub":"+25 XP minggu ini"}},{"kind":"phone","head":"Pintu kedua: fotomu","text":"Kapan saja, ketuk tanda + di foto profilmu. Setelah kisah minggu ini ditulis, tandanya berubah jadi centang dan fotomu mendapat cincin merah.","pos":"bottom","screen":"profileKisah","callout":{"side":"right","top":0.44,"tag":"Tanda +","title":"Di foto profilmu","sub":"kapan saja, bukan hanya akhir pekan"}},{"kind":"phone","head":"Tiga baris","text":"Satu kejadian nyata, apa yang kamu sadari, dan apa yang berubah. Tiga baris sudah cukup untuk satu Kisah.","pos":"bottom","screen":"kisah","callout":{"side":"right","top":0.46,"tag":"Tiga baris","title":"Kejadian · sadar · berubah"}},{"kind":"phone","head":"Kartumu","text":"Kamu memilih apa yang tampil di kartu, lalu membagikannya ke mana pun kamu mau.","pos":"top","screen":"kisahCard","callout":{"side":"right","top":0.43,"tag":"Kartumu","tagTone":"violet","title":"Bagikan ke mana pun"}},{"kind":"quiz","q":"Apa isi satu Kisah?","opts":["Rencana untuk minggu depan","Satu kejadian nyata, yang kamu sadari, dan yang berubah","Kutipan favoritmu"],"ans":1,"exp":"Benar! Tiga baris dari kejadian yang benar-benar kamu alami."},{"kind":"text","text":"Menuliskan perubahan membuatnya nyata dua kali: sekali saat terjadi, sekali saat kamu mengakuinya.","scene":"twice"},{"kind":"close","text":"Tiga baris, tiga menit, satu perubahan yang diakui.","cta":"Tulis Kisah pertamamu","scene":"avatarDoor"}]}$q$),
  ('T-11', $q${"lead":"Pengingat yang","accent":"tidak mengganggu","long":false,"slides":[{"kind":"cover","hook":"Pengingat yang salah jam akan kamu matikan. Yang tepat jam akan kamu tunggu.","scene":"bellClock"},{"kind":"phone","head":"Atur sendiri jamnya","text":"Jam pengingat ritual pagi, siang, dan malam bisa kamu atur sendiri. Pengingat belajar kelas pun bisa kamu tentukan jamnya.","pos":"bottom","screen":"notif","callout":{"side":"right","top":0.48,"tag":"06.30","title":"Priming (Pagi)","sub":"geser ke jam bangunmu"}},{"kind":"quiz","q":"Kapan pengingat paling efektif berbunyi?","opts":["Kapan saja, yang penting ada","Setelah kebiasaan lama mulai","Tepat sebelum kebiasaan lama mengambil alih"],"ans":2,"exp":"Benar! Tepat sebelum kebiasaan lama mengambil alih. Di situlah pengingat bekerja paling baik."},{"kind":"text","text":"Pengingat terbaik datang tepat sebelum kebiasaan lama mengambil alih. Taruh ia di sana, dan ia akan terasa seperti bantuan, bukan gangguan.","scene":"beforeHabit"},{"kind":"close","text":"Tepat jam, kamu tunggu.","cta":"Atur jam pengingat","scene":"bellClock"}]}$q$),
  ('T-12', $q${"lead":"Catatan Merlin dan Favorit:","accent":"supaya yang mengena tidak hilang","long":true,"slides":[{"kind":"cover","hook":"Jawaban terbaik Merlin sering datang saat kamu sedang tidak siap mencatat. Karena itu ada tempat menyimpannya.","scene":"threeKeepers"},{"kind":"phone","head":"Simpan ke Catatan","text":"Tahan jawaban Merlin yang mengena, lalu simpan ke Catatan. Ia menunggumu di sana kapan pun kamu kembali.","pos":"bottom","screen":"saveNote","callout":{"side":"right","top":0.58,"tag":"Tahan jawabannya","title":"★ Simpan ke Catatan"}},{"kind":"text","head":"Tiga tempat, satu tujuan","text":"Kutipan harian bisa difavoritkan. Artikel di Pojok Literasi bisa ditandai pita. Kamu tidak perlu mengingat semuanya; kamu tinggal kembali.","scene":"threeKeepers"},{"kind":"quiz","q":"Jawaban Merlin yang mengena, disimpan ke mana?","opts":["Catatan Merlin","Jurnal malam","Bookmarks Pojok Literasi"],"ans":0,"exp":"Benar! Ke Catatan Merlin. Kutipan ke Favorit, artikel ke pita."},{"kind":"split","a":"tidakSimpan","b":"simpan"},{"kind":"close","text":"Tidak perlu mengingat. Tinggal kembali.","cta":"Buka Catatan Merlin","scene":"threeKeepers"}]}$q$),
  ('F-01', $q${"lead":"Selamat datang di","accent":"Pojok Literasi","long":false,"slides":[{"kind":"cover","hook":"Ini bukan blog. Ini kotak kecil berisi satu pemahaman yang bisa kamu habiskan sambil menunggu pesanan datang.","scene":"timerCards"},{"kind":"text","head":"60 sampai 90 detik","text":"Tiap artikel di sini selesai dalam 60–90 detik. Tidak ada iklan, tidak ada komentar, tidak ada gulir tanpa ujung. Habis ya habis.","scene":"timerCards"},{"kind":"text","text":"Yang membuat orang berubah bukan banyaknya bacaan, melainkan satu kalimat yang pas, dibaca pada saat yang pas. Pojok ini dirancang untuk kalimat semacam itu.","scene":"oneSentence"},{"kind":"phone","head":"Tanda pita","text":"Ketuk tanda pita di bawah artikel yang mengena. Ia menunggumu di tab Bookmarks, kapan pun kamu kembali.","pos":"bottom","screen":"readerList","callout":{"side":"right","top":0.46,"tag":"Tab Bookmarks","title":"Yang kamu tandai pita","sub":"menunggumu di sini"}},{"kind":"quiz","q":"Berapa lama satu artikel di Pojok Literasi?","opts":["Tidak dibatasi","Lima menit","60 sampai 90 detik"],"ans":2,"exp":"Benar! Habis ya habis. Satu pemahaman, lalu kembali ke harimu."},{"kind":"close","text":"Satu kalimat yang pas, pada saat yang pas.","cta":"Mulai dari rak Tentang Realitas","scene":"oneSentence"}]}$q$),
  ('F-02', $q${"lead":"Modwiz itu apa,","accent":"sebenarnya?","long":false,"slides":[{"kind":"cover","hook":"Bukan aplikasi motivasi. Bukan pula aplikasi meditasi. Dua kata memegang semuanya.","scene":"realMagic"},{"kind":"split","a":"realitas","b":"keajaiban"},{"kind":"text","text":"Kebanyakan aplikasi memberimu alat. Modwiz berangkat dari keyakinan bahwa alatnya sudah ada di dalam dirimu, dan yang terjadi selama ini adalah sumbatan, bukan kekurangan.","scene":"blockedPipe"},{"kind":"quiz","q":"Dari mana Modwiz memulai?","opts":["Dari alat yang sudah ada di dalam dirimu","Dari motivasi harian","Dari alat yang baru"],"ans":0,"exp":"Benar! Yang terjadi selama ini sumbatan, bukan kekurangan."},{"kind":"close","text":"Realitas dan keajaiban. Keduanya milikmu.","cta":"Buka Ruang Mandala","scene":"threeRings"}]}$q$),
  ('F-03', $q${"lead":"Dari pendobrak perdukunan","accent":"ke pemberi keajaiban","long":true,"slides":[{"kind":"cover","hook":"Sebelum Modwiz ada, pendirinya dikenal karena satu hal: membongkar praktik perdukunan di televisi.","scene":"tvMagic"},{"kind":"text","text":"Bertahun-tahun ia membuktikan trik di balik \"keajaiban\" palsu. Lalu ia menemukan sesuatu yang lebih mengganggu: orang-orang tetap datang ke dukun, karena mereka memang membutuhkan rasa ajaib itu.","scene":"crowdDoor"},{"kind":"split","a":"bukanButuh","b":"siapaIsi"},{"kind":"text","text":"Maka keputusannya: berikan keajaiban yang asli, yang bisa dijelaskan, yang bekerja tanpa kemenyan dan tanpa tumbal.","scene":"realMagic"},{"kind":"quiz","q":"Menurut artikel ini, masalahnya di mana?","opts":["Orang membutuhkan rasa ajaib","Siapa yang mengisi kebutuhan itu","Acara televisinya"],"ans":1,"exp":"Benar! Kebutuhannya wajar. Yang diubah Modwiz adalah siapa yang mengisinya, dan dengan apa."},{"kind":"close","text":"Keajaiban yang asli: bisa dijelaskan, tetap terasa ajaib.","cta":"Baca \"Tiga hal yang tidak akan kami lakukan padamu\"","scene":"realMagic"}]}$q$),
  ('F-04', $q${"lead":"Merlin","accent":"bukan chatbot","long":false,"slides":[{"kind":"cover","hook":"Kamu bisa bertanya apa saja pada Merlin. Tetapi bukan itu gunanya.","scene":"orbChat"},{"kind":"list","head":"Yang dibaca Merlin","text":"Seluruh perjalananmu di aplikasi ini, lalu ia menyebutkan pola yang tidak kamu lihat sendiri.","rows":[{"color":"#f19e3f","glyph":"sun","name":"Check-in pagi","desc":"Perasaanmu dan tiga goal harimu."},{"color":"#413dd9","glyph":"moon","name":"Catatan malam","desc":"Apa yang terjadi, apa yang kamu pelajari."},{"color":"#7B5CD6","glyph":"rings","name":"Hasil Mandala","desc":"Ke mana kamu condong."},{"color":"#de4e66","glyph":"pen","name":"Goal yang kamu tulis dan lupakan","desc":"Merlin tidak lupa."}]},{"kind":"split","a":"chatbot","b":"merlinHalf"},{"kind":"text","text":"Karena itu Merlin tidak punya wajah. Ia bukan tokoh utama cerita ini. Kamu yang utama.","scene":"youMain"},{"kind":"quiz","q":"Apa beda Merlin dengan chatbot?","opts":["Merlin punya wajah","Merlin lebih cepat menjawab","Merlin membaca perjalananmu dan menyebut polanya"],"ans":2,"exp":"Benar! Chatbot menjawab pertanyaanmu. Merlin menjawab yang belum sempat kamu tanyakan."},{"kind":"close","text":"Kamu tokoh utamanya. Merlin yang membaca.","cta":"Bicara dengan Merlin","scene":"orbChat"}]}$q$),
  ('F-05', $q${"lead":"Tiga hal yang","accent":"tidak akan kami lakukan padamu","long":true,"slides":[{"kind":"cover","hook":"Sebelum kamu percaya pada aplikasi ini, kamu berhak tahu batasnya.","scene":"threeSeals"},{"kind":"list","head":"Tiga batas","rows":[{"color":"#f19e3f","glyph":"check","name":"Bekerja apa pun keyakinanmu","desc":"Pengguna yang taat beribadah tetap taat setelah memakainya."},{"color":"#de4e66","glyph":"x","name":"Tidak menjanjikan hasil","desc":"Tidak ada \"lakukan ini, dapatkan itu\"."},{"color":"#413dd9","glyph":"wheel","name":"Tidak mengambil alih kemudi","desc":"Ia menemani, bukan memutuskan."}]},{"kind":"text","text":"Aplikasi yang menjanjikan \"lakukan ini, dapatkan itu\" sedang menjual hal yang sama dengan dukun. Bedanya cuma kemasan. Kami memilih tidak ikut.","scene":"sameBox"},{"kind":"quiz","q":"Mana yang TIDAK dilakukan Modwiz?","opts":["Menjanjikan hasil","Bekerja apa pun keyakinanmu","Menemani perjalananmu"],"ans":0,"exp":"Benar! Modwiz tidak menjanjikan hasil, tidak memutuskan untukmu, dan bekerja apa pun keyakinanmu."},{"kind":"close","text":"Batasnya jelas, supaya kepercayaanmu punya dasar.","cta":"Lihat bagaimana Merlin membaca, bukan meramal","scene":"threeSeals"}]}$q$),
  ('F-06', $q${"lead":"Seribu gelang,","accent":"satu pertanyaan","long":false,"slides":[{"kind":"cover","hook":"Lebih dari seribu gelang pernah dikirim ke seluruh Indonesia. Pertanyaannya bukan \"apakah gelangnya bekerja\".","scene":"bracelet"},{"kind":"text","text":"Pertanyaannya: kenapa orang yang sama, setelah memakai gelang itu dan menjalani ritual paginya, mulai mengirim cerita perubahan ke grup, tanpa diminta. Salah satunya masih mengirim kabar enam tahun kemudian.","scene":"groupMessages"},{"kind":"split","a":"benda","b":"kebiasaan"},{"kind":"quiz","q":"Yang bekerja sebenarnya apa?","opts":["Gelangnya","Apa yang kamu lakukan tiap pagi saat menyentuhnya","Grup ceritanya"],"ans":1,"exp":"Benar! Gelangnya pengingat. Kebiasaannya yang bekerja."},{"kind":"close","text":"Gelangnya pengingat. Ritualnya yang bekerja, dan kini ada di aplikasi.","cta":"Coba Modwiz Priming","scene":"ritualCard"}]}$q$),
  ('F-07', $q${"lead":"Souls:","accent":"mata uang yang tidak bisa dibeli dengan uang saja","long":true,"slides":[{"kind":"cover","hook":"Souls bisa dibeli, benar. Tetapi Souls juga lahir dari hal yang tidak dijual.","scene":"soulBig"},{"kind":"list","head":"Tiga jalan yang tidak dijual","rows":[{"color":"#f19e3f","glyph":"refresh","name":"Streak 7, 30, 100 hari","desc":"Tiap tonggak menepati janji pada diri sendiri melahirkan Souls."},{"color":"#413dd9","glyph":"book","name":"Menamatkan course","desc":"Begitu course selesai, Souls kembali ke kantongmu sebagai cashback. Jumlahnya tertera di halaman course."},{"color":"#de4e66","glyph":"zap","name":"Top 3 papan peringkat","desc":"Tiap lesson selesai memberi 20 XP. Tiga XP tertinggi tiap minggu mendapat 50, 30, dan 15 Souls."}]},{"kind":"text","head":"Belajar juga membayar","text":"Lesson demi lesson mengumpulkan XP, dan di akhir course Souls-nya kembali. Jadi membeli course bukan pengeluaran saja: sebagian kembali sebagai Souls, sisanya sebagai XP yang bisa membawamu ke podium.","scene":"podium"},{"kind":"split","a":"beli","b":"peroleh"},{"kind":"phone","head":"Kalau mau beli","text":"Paket Souls ada di Eksplor Dirimu, satu Soul Rp990. Tetapi tonggak berikutnya mungkin lebih dekat dari yang kamu kira.","pos":"bottom","screen":"soulsShop","callout":{"side":"right","top":0.48,"tag":"Rp990","title":"per Soul"}},{"kind":"quiz","q":"Dari mana Souls bisa datang selain dibeli?","opts":["Dari Merlin","Dari membaca artikel","Dari streak, course yang tamat, dan Top 3 mingguan"],"ans":2,"exp":"Benar! Tiga jalan yang tidak dijual. Cara yang ini terasa lebih bangga."},{"kind":"close","text":"Dibeli, atau diperoleh. Yang kedua terasa lebih bangga.","cta":"Lihat streak-mu","scene":"milestones"}]}$q$),
  ('F-08', $q${"lead":"Modwiz Privilege,","accent":"dibaca pelan","long":false,"slides":[{"kind":"cover","hook":"\"Privilege\" di sini bukan hak istimewa untuk orang tertentu. Ia sesuatu yang kamu berikan pada dirimu sendiri.","scene":"mpCard"},{"kind":"list","head":"Isinya","rows":[{"color":"#f19e3f","glyph":"zap","name":"Energy Merlin tiga kali lipat","desc":"Lebih banyak obrolan bebas tiap hari dan tiap minggu."},{"color":"#413dd9","glyph":"clock","name":"Sesi kerja bersama lebih panjang","desc":"Merlin menemanimu lebih lama."},{"color":"#cb3bed","glyph":"heart","name":"Ingatan Merlin lebih dalam tentangmu","desc":"Bacaannya makin mengenalmu."},{"color":"#ffc600","glyph":"refresh","name":"Streak dinyalakan kembali gratis","desc":"Sekali tiap bulan."},{"color":"#de4e66","glyph":"book","name":"Seluruh Pojok Literasi terbuka","desc":"Semua rak, tanpa Souls."}]},{"kind":"text","text":"Hitung begini: harga sebulan setara segelas es teh sehari. Pertanyaannya bukan mahal atau murah, melainkan apakah kamu sedang serius dengan perjalananmu.","scene":"esTeh"},{"kind":"quiz","q":"Apa arti \"Privilege\" di Modwiz?","opts":["Sesuatu yang kamu berikan pada dirimu sendiri","Diskon untuk anggota lama","Hak istimewa untuk orang tertentu"],"ans":0,"exp":"Benar! Bukan diberikan pada orang tertentu. Kamu yang memberikannya pada dirimu."},{"kind":"close","text":"Bukan mahal atau murah. Serius, atau belum.","cta":"Lihat isi Modwiz Privilege","scene":"mpCard"}]}$q$),
  ('F-09', $q${"lead":"Tiga tahap,","accent":"satu peta","long":false,"slides":[{"kind":"cover","hook":"Setiap perjalanan di aplikasi ini berdiri di atas satu garis: dari tempatmu sekarang menuju tempat yang kamu inginkan.","scene":"stageLine"},{"kind":"list","head":"Tiga stage","text":"Semua ditulis dengan kata-katamu sendiri, bukan label dari kami.","rows":[{"color":"#de4e66","name":"Stage 1 · Realita Hari Ini","desc":"Keadaanmu hari ini."},{"color":"#cb3bed","name":"Stage 2 · Syaratnya","desc":"Satu syarat yang membuat Stage 3 mungkin terjadi. Yang paling sering diabaikan."},{"color":"#e2b24a","name":"Stage 3 · Impian Tercapai","desc":"Tujuanmu."}]},{"kind":"phone","head":"Di mana melihatnya","text":"Stage-mu tampil di Goal Saya dan di kartu milestone Realitas Saya, dengan kata-katamu sendiri.","pos":"top","screen":"realitas","callout":{"side":"left","top":0.3,"tag":"Stage 2 dari 3","tagTone":"violet","title":"Kata-katamu sendiri"}},{"kind":"text","text":"Orang gagal bukan karena tujuannya salah, melainkan karena melompat dari 1 ke 3 tanpa pernah menyebut apa yang harus benar di tengah.","scene":"jumpGap"},{"kind":"quiz","q":"Stage mana yang paling sering diabaikan?","opts":["Stage 1","Stage 2","Stage 3"],"ans":1,"exp":"Benar! Stage 2: satu syarat yang membuat Stage 3 mungkin. Tanpa itu orang melompat, dan jatuh."},{"kind":"close","text":"Sebut dulu yang harus benar di tengah.","cta":"Buka Goal Saya","scene":"stageLine"}]}$q$),
  ('F-10', $q${"lead":"Surat untuk yang mulai","accent":"di hari yang berat","long":false,"slides":[{"kind":"cover","hook":"Separuh orang memasang aplikasi ini saat hidupnya sedang tidak baik-baik saja. Kalau kamu salah satunya, surat ini untukmu.","scene":"letter"},{"kind":"text","text":"Kamu tidak perlu menulis goal besar hari ini. Kamu tidak perlu semangat.","scene":"noBigGoal"},{"kind":"phone","head":"CALM, tiga menit","text":"Satu sesi bernama CALM hanya meminta dua hal: apa yang sedang kamu pikirkan, dan apa yang kamu cari.","pos":"bottom","screen":"calm","callout":{"side":"right","top":0.46,"tag":"3 menit","title":"Dua pertanyaan saja"}},{"kind":"text","text":"Hari berat bukan waktu untuk membangun. Hari berat adalah waktu untuk tidak runtuh. Itu saja sudah kemajuan, dan aplikasi ini mencatatnya sebagai kemajuan.","scene":"standing"},{"kind":"close","text":"Tidak runtuh hari ini sudah kemajuan.","cta":"Mulai CALM, tiga menit","scene":"letter"}]}$q$),
  ('R-01', $q${"lead":"Gaun itu","accent":"biru-hitam atau putih-emas?","long":false,"slides":[{"kind":"cover","hook":"Pada 2015 satu foto gaun membelah internet menjadi dua kubu yang sama-sama yakin.","scene":"dressTwo"},{"kind":"split","a":"biruHitam","b":"putihEmas"},{"kind":"quiz","q":"Kenapa dua orang melihat warna berbeda pada foto yang sama?","opts":["Fotonya diedit","Matanya berbeda","Tebakan otaknya tentang cahaya berbeda"],"ans":2,"exp":"Benar! Mata sama sehatnya. Yang berbeda tebakan otak tentang cahaya di ruangan itu."},{"kind":"text","text":"Kamu tidak pernah melihat dunia. Kamu melihat tafsiran otakmu tentang dunia. Dan tafsiran bisa dilatih.","scene":"eyeBrain"},{"kind":"close","text":"Tafsiran bisa dilatih.","cta":"Buka Manas","scene":"manasBig"}]}$q$),
  ('R-02', $q${"lead":"Gorila yang","accent":"tidak kamu lihat","long":false,"slides":[{"kind":"cover","hook":"Dalam satu eksperimen terkenal, separuh orang gagal melihat seekor gorila yang berjalan melintasi layar.","scene":"gorilla"},{"kind":"text","text":"Mereka diminta menghitung operan bola. Di tengah video, orang berkostum gorila lewat, berhenti, memukul dada, lalu pergi. Sekitar separuh penonton bersumpah tidak ada gorila.","scene":"gorilla"},{"kind":"split","a":"lampuRuang","b":"sorotLampu"},{"kind":"quiz","q":"Perhatian itu seperti apa?","opts":["Sorot lampu: menerangi yang kamu pilih","Kamera: merekam semua","Lampu ruangan: menerangi semua"],"ans":0,"exp":"Benar! Yang kamu sorot tiap pagi menentukan gorila mana yang kamu lihat, dan mana yang kamu lewatkan."},{"kind":"close","text":"Tiga goal pagimu adalah arah sorot lampunya.","cta":"Tulis tiga goal pagimu","scene":"spotlight"}]}$q$),
  ('R-03', $q${"lead":"Yang kamu lihat, dengar, dan rasakan","accent":"belum tentu fakta","long":true,"slides":[{"kind":"cover","hook":"Kalimat ini diucapkan seorang pesulap yang pekerjaannya membongkar penipuan.","scene":"maskHat"},{"kind":"list","head":"Resep penipu","text":"Penipu tidak perlu menipu matamu. Sisanya otakmu yang mengisi.","rows":[{"color":"#de4e66","glyph":"mask","name":"Penampilan yang tampak suci","desc":"Mata percaya pada kesan pertama."},{"color":"#413dd9","glyph":"ear","name":"Kata-kata yang tampak santun","desc":"Telinga percaya pada nada."},{"color":"#f19e3f","glyph":"flag","name":"Satu klaim yang tidak bisa kamu periksa","desc":"Otak mengisi sisanya."}]},{"kind":"text","head":"Prinsip tua","text":"Penjelasan paling sederhana biasanya yang paling benar. Sebelum percaya pada sesuatu yang ajaib, cari dulu penjelasan yang membosankan. Kalau tidak ada, barulah takjub.","scene":"simpleFirst"},{"kind":"quiz","q":"Sebelum percaya pada yang ajaib, apa langkah pertamanya?","opts":["Takjub dulu","Cari penjelasan yang membosankan","Tanya orang yang lebih tahu"],"ans":1,"exp":"Benar! Cari yang membosankan dulu. Kalau tidak ada, barulah takjub."},{"kind":"close","text":"Cari yang membosankan dulu. Baru takjub.","cta":"Baca \"Tiga ruangan: Delusi, Ilusi, Realita\"","scene":"maskHat"}]}$q$),
  ('R-04', $q${"lead":"Tiga ruangan: ","accent":"Delusi, Ilusi, Realita","long":false,"slides":[{"kind":"cover","hook":"Setiap keputusan besar dalam hidupmu dibuat di ruangan yang bukan ruang fakta.","scene":"threeRooms"},{"kind":"list","head":"Tiga ruangan","rows":[{"color":"#cb3bed","name":"Delusi","desc":"Tempat gambaran masa depan yang kamu inginkan tinggal."},{"color":"#f19e3f","name":"Ilusi","desc":"Tempat cerita yang kamu percayai tentang dirimu."},{"color":"#1a1c21","name":"Realita","desc":"Tempat uang, waktu, dan tubuh."}]},{"kind":"text","text":"Orang biasa terjebak di satu ruangan. Yang lincah berpindah dalam sepersekian detik.","scene":"roomHop"},{"kind":"text","text":"Delusi bukan penyakit. Ia bahan baku. Semua yang kini nyata pernah mulai sebagai bayangan di kepala seseorang yang berani memasuki ruang itu, lalu keluar membawa rencana.","scene":"cloudToHouse"},{"kind":"quiz","q":"Di ruangan mana Stage 3-mu ditulis?","opts":["Ilusi","Realita","Delusi"],"ans":2,"exp":"Benar! Stage 3 ditulis di ruang Delusi. Stage 2 adalah pintunya ke Realita."},{"kind":"close","text":"Masuk ke ruang Delusi, keluar membawa rencana.","cta":"Buka Goal Saya","scene":"threeRooms"}]}$q$),
  ('R-05', $q${"lead":"Fisik dan metafisik: ","accent":"dua lantai dari rumah yang sama","long":true,"slides":[{"kind":"cover","hook":"Kata \"metafisik\" membuat sebagian orang curiga. Padahal artinya sederhana: yang di luar fisik.","scene":"twoFloors"},{"kind":"split","a":"fisik","b":"metafisik"},{"kind":"text","text":"Orang yang hanya mengurus lantai fisik akan sibuk tanpa arah. Yang hanya tinggal di lantai metafisik akan penuh arah tanpa bergerak. Perubahan terjadi di tangga di antara keduanya.","scene":"stairs"},{"kind":"quiz","q":"Di mana perubahan terjadi?","opts":["Di tangga di antara keduanya","Di lantai metafisik","Di lantai fisik"],"ans":0,"exp":"Benar! Di tangganya. Arah dari atas, gerak dari bawah."},{"kind":"close","text":"Tiga goal pagimu adalah tangga itu.","cta":"Mulai ritual pagi","scene":"ritualCard"}]}$q$),
  ('R-06', $q${"lead":"Kontraktor","accent":"realita","long":false,"slides":[{"kind":"cover","hook":"Kalau hidupmu terasa sedang dibongkar, mungkin kamu sedang direnovasi.","scene":"renovation"},{"kind":"text","text":"Tidak ada rumah yang bisa diubah tanpa ada dinding yang dirobohkan, debu di mana-mana, dan beberapa minggu tidur di ruangan yang tidak nyaman. Perubahan realita bekerja persis seperti itu.","scene":"renovation"},{"kind":"split","a":"kontraktor","b":"penghuni"},{"kind":"quiz","q":"Ketidaknyamanan saat berubah, tandanya apa?","opts":["Kamu salah jalan","Pekerjaan sedang berlangsung","Harus berhenti"],"ans":1,"exp":"Benar! Sering kali ia tanda pekerjaan sedang berlangsung. Pertanyaannya: kamu kontraktornya?"},{"kind":"coba","text":"Tulis tiga hal baik di sekitarmu hari ini, dan satu perbedaan antara realitamu dulu dengan hari ini.","scene":"notebook"},{"kind":"close","text":"Kamu kontraktornya.","cta":"Tulis di jurnal malam","scene":"renovation"}]}$q$),
  ('R-07', $q${"lead":"Kalau semua uang di dunia","accent":"dibagi rata","long":false,"slides":[{"kind":"cover","hook":"Andai seluruh uang di dunia dikumpulkan lalu dibagi rata, apa yang terjadi lima tahun kemudian?","scene":"coinsEqual"},{"kind":"quiz","q":"Lima tahun kemudian, apa yang terjadi?","opts":["Semua jadi kaya","Semua tetap sama rata","Yang kaya kembali kaya, yang miskin kembali miskin"],"ans":2,"exp":"Benar! Bukan karena kecerdasan. Karena rasa \"wajar\"."},{"kind":"split","a":"sumpit","b":"tangan"},{"kind":"text","text":"Realita yang kamu tinggali hari ini adalah realita yang terasa wajar bagimu. Untuk pindah, kamu tidak perlu lebih pintar. Kamu perlu membiasakan diri dengan yang belum wajar, sampai ia wajar.","scene":"newNormal"},{"kind":"close","text":"Kebiasaan dihitung dalam hari, bukan niat.","cta":"Lihat streak-mu","scene":"newNormal"}]}$q$),
  ('R-08', $q${"lead":"Kebutuhan mengalahkan","accent":"seratus keinginan","long":false,"slides":[{"kind":"cover","hook":"Ingat sesuatu yang bertahun-tahun kamu inginkan, lalu tiba-tiba kamu dapatkan dalam waktu singkat?","scene":"house"},{"kind":"text","text":"Biasanya ada satu perubahan kecil sebelumnya: keinginan itu berubah menjadi kebutuhan.","scene":"wantNeed"},{"kind":"split","a":"ingin","b":"butuh"},{"kind":"quiz","q":"Apa yang biasanya berubah sebelum sesuatu yang lama diinginkan akhirnya didapat?","opts":["\"Ingin\" berubah menjadi \"butuh\"","Punya lebih banyak waktu luang","Berdoa lebih keras"],"ans":0,"exp":"Benar! Perubahannya kecil dan di dalam: alasan yang jujur kenapa kamu membutuhkannya."},{"kind":"text","text":"Satu kebutuhan jauh lebih kuat daripada seratus keinginan. Keahlian orang yang cepat mendapatkan sesuatu bukan berdoa lebih keras, melainkan menggeser \"ingin\" menjadi \"butuh\", dengan alasan yang jujur.","scene":"scale"},{"kind":"coba","text":"Ambil satu keinginanmu. Tulis tiga alasan kenapa kamu membutuhkannya, bukan sekadar menginginkannya.","scene":"notebook"},{"kind":"close","text":"Bukan berdoa lebih keras. Menggeser \"ingin\" menjadi \"butuh\".","cta":"Buka Goal Saya","scene":"wantNeed"}]}$q$),
  ('R-09', $q${"lead":"Lampu merah tidak pernah","accent":"bilang \"berhenti\"","long":false,"slides":[{"kind":"cover","hook":"Tidak ada tulisan \"berhenti sampai hijau menyala\" di lampu lalu lintas. Tetapi kamu berhenti.","scene":"trafficLight"},{"kind":"text","text":"Kita hidup di antara simbol. Warna, bentuk, bunyi, yang diterjemahkan otak dalam sepersekian detik tanpa perlu kalimat. Itulah sebabnya kartu, gelang, atau satu kata di layar bisa mengarahkan tindakan.","scene":"symbols"},{"kind":"split","a":"simbolLain","b":"simbolSendiri"},{"kind":"quiz","q":"Apa pertanyaan yang tepat soal simbol?","opts":["Apakah aku terpengaruh simbol?","Simbol siapa yang mengisi hariku?","Bagaimana menghindari simbol?"],"ans":1,"exp":"Benar! Kamu sudah pasti terpengaruh. Yang bisa kamu pilih: simbol siapa."},{"kind":"close","text":"Satu simbol yang kamu pilih sendiri, setiap pagi.","cta":"Lihat Fokusmu Hari Ini","scene":"symbols"}]}$q$),
  ('R-10', $q${"lead":"Tiga keterampilan","accent":"menyusuri realita","long":false,"slides":[{"kind":"cover","hook":"Saat perjalanan terasa berat, kebanyakan orang menambah kecepatan. Yang dibutuhkan justru tiga keterampilan lain.","scene":"threeStones"},{"kind":"list","head":"Present, Peace, Believe","rows":[{"color":"#413dd9","name":"Present","desc":"Tarik napas, lihat sekeliling, sebutkan apa yang sudah kamu miliki."},{"color":"#f19e3f","name":"Peace","desc":"Masa lalu hanyalah kejadian yang harus terjadi agar kamu sampai di sini."},{"color":"#cb3bed","name":"Believe","desc":"Percayai masa depan yang sedang kamu bentuk, dan jangan mengubah keinginanmu tiap minggu."}]},{"kind":"text","text":"Rumah tidak kunjung selesai kalau pemiliknya mengganti denah setiap kali debu beterbangan.","scene":"blueprints"},{"kind":"quiz","q":"Saat perjalanan terasa berat, yang dibutuhkan apa?","opts":["Mengganti tujuan","Menambah kecepatan","Present, Peace, Believe"],"ans":2,"exp":"Benar! Hadir, berdamai, percaya. Bukan lebih cepat."},{"kind":"close","text":"Present dulu. Tiga menit.","cta":"Mulai CALM","scene":"threeStones"}]}$q$),
  ('R-11', $q${"lead":"Gila kalau berharap hasil berbeda","accent":"dengan cara yang sama","long":true,"slides":[{"kind":"cover","hook":"Realitamu tidak berubah? Ada tiga kemungkinan, dan ketiganya punya resep berbeda.","scene":"threeWays"},{"kind":"list","head":"Tiga kemungkinan","text":"Yang tidak ada dalam daftar: mengulang hal yang sama, di tempat yang sama, dengan orang yang sama, lalu berharap beda.","rows":[{"color":"#de4e66","name":"Tidak berubah sama sekali","desc":"Butuh fokus dan energi lebih."},{"color":"#f19e3f","name":"Berubah tetapi tidak sesuai","desc":"Butuh waktu lebih panjang."},{"color":"#413dd9","name":"Berubah perlahan","desc":"Teruskan."}]},{"kind":"text","head":"Siklusnya","text":"Potensi, tindakan, hasil, keyakinan, lalu kembali ke potensi yang lebih besar. Kebanyakan orang berhenti di hasil, karena hasilnya tidak seperti yang dibayangkan.","scene":"cycle"},{"kind":"text","text":"Padahal hasil negatif dan positif sama-sama memutar siklusnya.","scene":"cycle"},{"kind":"quiz","q":"Di mana kebanyakan orang berhenti?","opts":["Di hasil","Di keyakinan","Di potensi"],"ans":0,"exp":"Benar! Di hasil, karena tidak seperti yang dibayangkan. Padahal hasil apa pun memutar siklusnya."},{"kind":"close","text":"Hasil apa pun memutar siklusnya. Jangan berhenti di situ.","cta":"Buka Realitas Saya","scene":"rsGridBig"}]}$q$),
  ('R-12', $q${"lead":"Kenapa setelah menulis goal","accent":"kamu mulai melihatnya di mana-mana","long":true,"slides":[{"kind":"cover","hook":"Pernah memutuskan membeli mobil tertentu, lalu tiba-tiba mobil itu ada di setiap jalan?","scene":"carsRoad"},{"kind":"text","text":"Mobilnya tidak bertambah. Perhatianmu yang berubah. Fenomena ini punya nama dalam psikologi, dan ia terjadi pada apa pun yang baru saja kamu putuskan penting.","scene":"filter"},{"kind":"phone","head":"Menulis goal","text":"Menulis goal bukan ritual mistis. Ia cara memberi tahu sistem penyaring di kepalamu: mulai sekarang, yang ini penting.","pos":"top","screen":"goals","callout":{"side":"left","top":0.3,"tag":"Penyaring diberi tahu","tagTone":"violet","title":"Yang ini penting"}},{"kind":"text","text":"Setelah itu peluang terlihat, bukan karena ia muncul, melainkan karena kamu berhenti melewatkannya.","scene":"carsRoad"},{"kind":"quiz","q":"Kenapa mobil itu tiba-tiba ada di mana-mana?","opts":["Mobilnya bertambah","Perhatianmu berubah","Kebetulan saja"],"ans":1,"exp":"Benar! Perhatianmu yang berubah. Peluang pun begitu."},{"kind":"close","text":"Bukan muncul. Kamu berhenti melewatkannya.","cta":"Tulis ulang Stage 2-mu dalam satu kalimat","scene":"filter"}]}$q$),
  ('M-01', $q${"lead":"Ruang Mandala: ","accent":"tiga alat, satu pertanyaan","long":false,"slides":[{"kind":"cover","hook":"Tiga alat ini tidak menanyakan siapa kamu. Mereka menanyakan apa yang selama ini sudah bekerja untukmu.","scene":"threeRings"},{"kind":"list","head":"Tiga alat, tiga bacaan","rows":[{"img":"agni","name":"Agni Chakti","desc":"Membaca kecenderungan tindakanmu."},{"img":"manas","name":"Manas","desc":"Membaca dari bahan indra apa kamu merangkai dunia."},{"img":"svadharma","name":"Svadharma","desc":"Membaca ke arah mana kamu sebenarnya menghadap."}]},{"kind":"text","head":"Ruang mengenal diri","text":"Banyak orang menjalani hidup tanpa benar-benar mengenal dirinya. Mandala adalah ruang untuk mengenalnya. Dan begitu kamu kenal, realita yang selama ini kamu kira tidak mungkin, mulai bisa kamu ciptakan.","scene":"mirrorRoom"},{"kind":"phone","head":"Di mana Ruang Mandala","text":"Di Eksplor Dirimu, rak Mandala. Agni Chakti terbuka begitu Milestone Saya-mu ada; Manas dan Svadharma dibuka dengan Souls.","pos":"top","screen":"mandala","callout":{"side":"left","top":0.3,"tag":"Mulai di sini","title":"Agni Chakti","sub":"Terbuka begitu milestone-mu ada."}},{"kind":"split","a":"tipeLabel","b":"pola"},{"kind":"quiz","q":"Apa yang kamu dapat dari Mandala?","opts":["Mengenal dirimu: bahan untuk mencipta realita yang kamu kira mustahil","Ramalan","Tipe kepribadian"],"ans":0,"exp":"Benar! Bukan tipe. Kamu mengenal dirimu, dan dari situ realita yang kamu kira mustahil mulai bisa dibentuk."},{"kind":"close","text":"Kenali dirimu di sini. Realita yang kamu kira mustahil dimulai dari situ.","cta":"Mulai Agni Chakti","scene":"threeRings"}]}$q$),
  ('M-02', $q${"lead":"Kamu tidak diminta","accent":"menebak kekuatanmu","long":false,"slides":[{"kind":"cover","hook":"\"Apa kelebihanmu?\" adalah pertanyaan paling sulit di dunia. Karena itu Mandala tidak menanyakannya.","scene":"blankForm"},{"kind":"split","a":"tulisSendiri","b":"pilihDua"},{"kind":"phone","head":"Dua hal yang sama-sama sah","text":"Disiplin atau spontan? Rencana atau tindakan? Tidak ada yang lebih baik. Kamu memilih yang memang kamu; Merlin yang menyebut polanya.","pos":"bottom","screen":"agniPair","callout":{"side":"right","top":0.48,"tag":"Pasangan 1 dari 30","title":"Keduanya terhormat"}},{"kind":"text","head":"Potensi adalah keluaran","text":"Orang jarang tahu kekuatannya karena ia terasa biasa saja. Yang terasa biasa bagimu, justru itu yang orang lain tidak bisa.","scene":"ordinaryGem"},{"kind":"quiz","q":"Kenapa orang sulit menyebut kekuatannya sendiri?","opts":["Karena rendah hati","Karena kekuatan itu terasa biasa saja baginya","Karena belum pernah dites"],"ans":1,"exp":"Benar! Yang terasa biasa bagimu, justru itu yang orang lain tidak bisa."},{"kind":"close","text":"Kamu tidak perlu menebak. Pilih saja; polanya akan disebut.","cta":"Buka Ruang Mandala","scene":"ordinaryGem"}]}$q$),
  ('M-03', $q${"lead":"Agni Chakti: 30 pilihan,","accent":"tidak ada jawaban salah","long":true,"slides":[{"kind":"cover","hook":"\"Melihat fakta\" atau \"melihat cerita di baliknya\"? Keduanya benar. Itu intinya.","scene":"agniBig"},{"kind":"phone","head":"Dua lembar, tiga puluh pasang","text":"Lembar pertama: kiri atau kanan. Lembar kedua: depan atau belakang. Tiap pasang sengaja sama-sama terhormat, supaya kamu memilih yang memang kamu, bukan yang terdengar lebih baik.","pos":"top","screen":"agniPair","callout":{"side":"left","top":0.3,"tag":"Lembar 1","title":"Disiplin · Spontan"}},{"kind":"list","head":"Empat kecenderungan","text":"Dari 30 pilihan terbaca empat kecenderungan bertindak. Semua punya kekuatannya.","rows":[{"color":"#de4e66","name":"Pendobrak","desc":"Membuka jalan, memimpin."},{"color":"#f19e3f","name":"Performer","desc":"Mencairkan suasana, menggerakkan orang."},{"color":"#413dd9","name":"Peneliti","desc":"Mencari bukti sebelum melangkah."},{"color":"#8fdc9a","name":"Pendamai","desc":"Menjaga semua tetap utuh."}]},{"kind":"text","head":"Sebelum mulai","text":"Agni Chakti meminta satu hal: Milestone Saya-mu sudah ada. Karena yang diukur adalah kecenderunganmu menuju sesuatu, bukan di ruang hampa.","scene":"milestoneDoor"},{"kind":"text","text":"Alat ini bukan tentang apa yang menyala dalam dirimu. Ia tentang apa yang sudah menyala, dan selama ini kamu anggap wajar.","scene":"flameAlready"},{"kind":"quiz","q":"Kenapa tiap pasang pilihan dibuat sama-sama terhormat?","opts":["Supaya cepat selesai","Supaya tesnya terasa adil","Supaya kamu memilih yang memang kamu, bukan yang terdengar lebih baik"],"ans":2,"exp":"Benar! Tidak ada jawaban salah, maka tidak ada yang perlu dipoles."},{"kind":"close","text":"Yang sudah menyala, dan kamu anggap wajar.","cta":"Mulai Agni Chakti","scene":"agniBig"}]}$q$),
  ('M-04', $q${"lead":"Manas: dari bahan apa","accent":"kamu merangkai dunia","long":true,"slides":[{"kind":"cover","hook":"Dua orang menonton film yang sama. Satu mengingat warnanya, satu mengingat dialognya. Keduanya menonton film yang berbeda.","scene":"twoViewers"},{"kind":"list","head":"Lima bahan indra","text":"Manas menamai bahan yang paling sering dipakai pikiranmu untuk menyusun pengalaman.","rows":[{"color":"#e2b24a","name":"Penglihatan","desc":"Apa yang kamu lihat."},{"color":"#5fb8a8","name":"Pendengaran","desc":"Apa yang kamu dengar."},{"color":"#de4e66","name":"Sentuhan dan gerak","desc":"Apa yang terasa di badanmu."},{"color":"#8fdc9a","name":"Pengecapan","desc":"Rasa dan bau: lidah dan hidungmu."},{"color":"#cb3bed","name":"Suara dalam kepala","desc":"Kata-kata di kepalamu."}]},{"kind":"phone","head":"Delapan belas pilihan, enam tugas","text":"Delapan belas situasi dengan dua jawaban, lalu enam tugas membayangkan: wajah yang kamu lihat tiap hari, suara ibumu memanggil, tekstur handuk basah, gigitan jeruk nipis. Tidak ada yang lebih baik; ada yang lebih kamu.","pos":"bottom","screen":"manasItem","callout":{"side":"right","top":0.5,"tag":"Tugas 2 dari 6","title":"Suara ibumu memanggil namamu."}},{"kind":"text","head":"Dua hal berubah","text":"Begitu kamu tahu bahanmu: cara kamu belajar, dan cara kamu menjelaskan sesuatu pada orang yang bahannya berbeda.","scene":"learnExplain"},{"kind":"quiz","q":"Apa yang dinamai Manas?","opts":["Bahan indra yang paling sering dipakai pikiranmu","Bakat terpendammu","Tipe kepribadianmu"],"ans":0,"exp":"Benar! Bukan yang lebih baik. Yang lebih kamu."},{"kind":"close","text":"Bukan yang lebih baik. Yang lebih kamu.","cta":"Mulai Manas","scene":"manasBig"}]}$q$),
  ('M-05', $q${"lead":"Svadharma: arah pulang terbaca","accent":"dari yang kamu tolak lepaskan","long":true,"slides":[{"kind":"cover","hook":"Kamu bisa berbohong tentang apa yang kamu inginkan. Sulit berbohong tentang apa yang tidak rela kamu lepaskan.","scene":"compass"},{"kind":"phone","head":"Delapan belas persimpangan","text":"Di tiap persimpangan kamu harus merelakan satu hal. Sabtu kosongmu: proyek pribadi yang macet, atau keluarga besar yang kumpul?","pos":"top","screen":"svadCross","callout":{"side":"left","top":0.3,"tag":"Persimpangan 1 dari 18","title":"Satu hal harus hilang"}},{"kind":"list","head":"Empat arah","text":"Dari pola yang kamu pertahankan terbaca ke mana kamu menghadap.","rows":[{"color":"#e6a663","name":"Karya","desc":"Membangun sesuatu yang lahir dari tanganmu sendiri."},{"color":"#e6a663","name":"Gema","desc":"Didengar, dan menjangkau banyak orang."},{"color":"#e6a663","name":"Ikatan","desc":"Hadir utuh untuk orang-orang yang kamu jaga."},{"color":"#e6a663","name":"Kendali","desc":"Waktu dan keputusan tetap di tanganmu."}]},{"kind":"split","a":"diucapkan","b":"dipertahankan"},{"kind":"text","head":"Energi inti","text":"Setiap pilihan yang kamu pertahankan menunjuk ke satu energi inti: yang menggerakkanmu jauh sebelum dunia menuntut macam-macam. Svadharma tidak menyuruhmu lari ke tempat baru. Ia mengantarmu pulang ke sana, seperti pulang ke rumah setelah perjalanan panjang.","scene":"homeDirection"},{"kind":"quiz","q":"Setelah 18 persimpangan, Svadharma mengantarmu ke mana?","opts":["Ke tujuan baru yang lebih besar","Pulang ke energi intimu, seperti pulang ke rumah setelah perjalanan panjang","Ke jawaban yang paling terdengar bagus"],"ans":1,"exp":"Benar! Bukan tempat baru. Rumahmu sendiri, yang kamu tinggalkan sepanjang perjalanan."},{"kind":"close","text":"Pulang ke energi intimu. Rumahmu sudah ada sejak awal.","cta":"Mulai Svadharma","scene":"compass"}]}$q$),
  ('M-06', $q${"lead":"Kenapa hasilnya","accent":"bukan tipe kepribadian","long":false,"slides":[{"kind":"cover","hook":"Pada 1948 seorang psikolog memberi mahasiswanya \"analisis kepribadian pribadi\". Semua mendapat teks yang sama persis. Rata-rata menilainya sangat akurat.","scene":"sameSheets"},{"kind":"quiz","q":"Kenapa teks yang sama terasa akurat untuk semua orang?","opts":["Mahasiswanya mirip","Psikolognya hebat","Kalimatnya umum, cocok untuk siapa saja"],"ans":2,"exp":"Benar! Itulah jebakan tes kepribadian: ia cocok karena ia umum."},{"kind":"text","text":"\"Kamu butuh disukai, tetapi kadang kritis pada diri sendiri.\" Terasa pas? Terasa pas juga untuk tetanggamu.","scene":"barnumLine"},{"kind":"split","a":"tipe","b":"silang"},{"kind":"text","head":"Tidak bisa dipasang pada orang lain","text":"Pola yang muncul dari tindakanmu sendiri tidak bisa dipasang pada orang lain. Itulah bedanya bahan dan label.","scene":"fingerprint"},{"kind":"close","text":"Cocok karena umum, atau benar karena darimu.","cta":"Lihat hasil Mandala terakhirmu","scene":"fingerprint"}]}$q$),
  ('M-07', $q${"lead":"Tiga bulan","accent":"kemudian","long":false,"slides":[{"kind":"cover","hook":"Agni Chakti memintamu kembali setelah tiga bulan. Bukan karena hasilnya kedaluwarsa.","scene":"timeline"},{"kind":"text","text":"Dalam tiga bulan, orang yang menjalani ritual harian biasanya bergeser. Bukan berubah total, bergeser. Alat ini dibuat untuk menangkap pergeseran itu.","scene":"shiftBars"},{"kind":"phone","head":"Kapan bisa diulang","text":"Sembilan puluh hari setelah pengukuran terakhir, atau lebih cepat kalau milestone-mu berganti. Tombolnya ada di bawah hasilmu.","pos":"bottom","screen":"agniHasil","callout":{"side":"right","top":0.5,"tag":"90 hari","title":"Ukur lagi","sub":"atau saat milestone berganti"}},{"kind":"split","a":"foto","b":"film"},{"kind":"quiz","q":"Kenapa Agni Chakti diulang setelah tiga bulan?","opts":["Untuk menangkap pergeseran yang terjadi","Supaya dapat XP lagi","Hasilnya kedaluwarsa"],"ans":0,"exp":"Benar! Hasil pertama foto, hasil kedua film. Merlin menyebut apa yang berbeda."},{"kind":"close","text":"Hasil pertama foto. Hasil kedua film.","cta":"Cek kapan Agni Chakti-mu bisa diulang","scene":"timeline"}]}$q$),
  ('M-08', $q${"lead":"Cara membaca Pembacaan Merlin","accent":"tanpa membela diri","long":true,"slides":[{"kind":"cover","hook":"Reaksi pertama pada bacaan yang tepat biasanya \"ah, tidak juga\".","scene":"shieldText"},{"kind":"phone","head":"Yang belum kamu sebut sendiri","text":"Di bawah hasil Agni Chakti, Merlin menulis bagian ini dari jawabanmu sendiri dan milestone-mu. Bagian inilah yang paling sering ditolak dulu.","pos":"top","screen":"agniHasil","callout":{"side":"left","top":0.3,"tag":"Pembacaan Merlin","tagTone":"violet","title":"Yang belum kamu sebut sendiri"}},{"kind":"list","head":"Tiga langkah","rows":[{"color":"#413dd9","glyph":"book","name":"Baca sekali tanpa berhenti","desc":"Jangan menjawab di kepala."},{"color":"#f19e3f","glyph":"clock","name":"Tutup. Besok pagi baca lagi","desc":"Dengan kepala yang lain."},{"color":"#de4e66","glyph":"eye","name":"Lalu tanya","desc":"Di mana minggu ini aku melakukan persis seperti itu?"}]},{"kind":"split","a":"asing","b":"mengganggu"},{"kind":"text","head":"Kenapa mengganggu?","text":"Karena banyak orang mau perubahan, tetapi tidak mau berubah. Yang sekarang sudah terasa nyaman. Bacaan yang benar menunjuk tepat ke kenyamanan itu, dan di situlah rasa terganggunya datang.","scene":"comfyChair"},{"kind":"quiz","q":"Bacaan yang benar biasanya terasa bagaimana?","opts":["Menyenangkan","Mengganggu","Asing"],"ans":1,"exp":"Benar! Yang asing itu salah sasaran. Yang mengganggu menunjuk ke kenyamanan yang enggan kamu tinggalkan."},{"kind":"coba","text":"Simpan satu kalimat yang paling mengganggu ke Catatan Merlin. Baca lagi minggu depan.","scene":"noteStar"},{"kind":"close","text":"Yang mengganggu itulah yang berguna.","cta":"Buka Catatan Merlin","scene":"noteStar"}]}$q$),
  ('M-09', $q${"lead":"Kalau dua orang","accent":"sama-sama memakai Manas","long":false,"slides":[{"kind":"cover","hook":"Pertengkaran yang paling melelahkan sering bukan soal isi, melainkan soal bahan.","scene":"twoBubbles"},{"kind":"split","a":"gambaran","b":"kalimat"},{"kind":"text","text":"Begitu masing-masing tahu bahan indranya, percakapan yang sama berubah nada.","scene":"sameTalkNewTone"},{"kind":"phone","head":"Tunjukkan hasilmu","text":"Halaman Jalur Utamamu bisa kamu tunjukkan pada orang terdekat. Bahan yang berbeda bukan salah siapa pun.","pos":"bottom","screen":"manasHasil","callout":{"side":"right","top":0.46,"tag":"Jalur utamamu","title":"Penglihatan"}},{"kind":"quiz","q":"Memahami bahan orang lain itu untuk apa?","opts":["Memenangkan perdebatan","Mengendalikannya","Berhenti saling melewatkan"],"ans":2,"exp":"Benar! Bukan cara mengendalikan. Cara berhenti saling melewatkan."},{"kind":"close","text":"Berhenti saling melewatkan.","cta":"Bagikan Manas ke satu orang terdekat","scene":"sameTalkNewTone"}]}$q$),
  ('M-10', $q${"lead":"Pola yang tidak bisa","accent":"kamu lihat sendiri","long":false,"slides":[{"kind":"cover","hook":"Ada hal tentang dirimu yang hanya bisa dilihat dari luar, dan bukan oleh orang lain.","scene":"outsideView"},{"kind":"list","head":"Yang Merlin ingat, kamu tidak","rows":[{"color":"#f19e3f","glyph":"clock","name":"Jam kamu biasanya absen check-in","desc":"Malam yang sama, tiap minggu."},{"color":"#8fdc9a","glyph":"check","name":"Goal yang selalu tercentang","desc":"Dan jenis yang selalu terbawa ke esok."},{"color":"#413dd9","glyph":"pen","name":"Kata yang paling sering muncul","desc":"Di jurnal malammu."}]},{"kind":"text","head":"Jarak","text":"Kamu terlalu dekat dengan hidupmu untuk melihat polanya. Itu bukan kekurangan; itu jarak. Mandala dan catatan harian memberi Merlin jarak yang kamu tidak punya.","scene":"tooClose"},{"kind":"phone","head":"Tanyakan langsung","text":"Satu pertanyaan ke Merlin: pola apa yang kamu lihat dari sebulan terakhir? Jawabannya dari catatanmu sendiri.","pos":"top","screen":"merlinPola","callout":{"side":"left","top":0.3,"tag":"Dari catatanmu","tagTone":"violet","title":"Tiga kali, malam yang sama"}},{"kind":"quiz","q":"Kenapa kamu sulit melihat polamu sendiri?","opts":["Terlalu dekat dengan hidupmu sendiri","Polanya tidak ada","Kurang teliti"],"ans":0,"exp":"Benar! Bukan kekurangan. Jarak."},{"kind":"close","text":"Bukan kekurangan. Jarak.","cta":"Tanya Merlin: \"pola apa yang kamu lihat dari sebulan terakhir?\"","scene":"outsideView"}]}$q$),
  ('M-11', $q${"lead":"Mandala dan","accent":"Stage 2-mu","long":false,"slides":[{"kind":"cover","hook":"Hasil Mandala yang tidak dipakai untuk apa-apa hanya jadi bacaan menarik. Begini cara memakainya.","scene":"stageAgni"},{"kind":"phone","head":"Ambil Stage 2-mu","text":"Satu syarat yang membuat tujuanmu mungkin. Ia ada di kartu milestone-mu, dengan kata-katamu sendiri.","pos":"top","screen":"realitas","callout":{"side":"left","top":0.3,"tag":"Stage 2 dari 3","tagTone":"violet","title":"Syaratnya"}},{"kind":"split","a":"membantu","b":"menghambat"},{"kind":"coba","text":"Tulis Stage 2-mu dalam satu kalimat. Di sebelahnya, satu kecenderungan dari Agni Chakti-mu yang membantunya, dan satu yang menghambatnya.","scene":"notebook"},{"kind":"text","text":"Alat tidak mengubah apa pun. Alat yang dipasangkan dengan satu goal yang jelas mengubah cara kamu mengambil langkah besok pagi.","scene":"toolGoal"},{"kind":"quiz","q":"Kapan hasil Mandala mulai bekerja?","opts":["Begitu selesai diukur","Saat dipasangkan dengan satu goal yang jelas","Setelah dibaca Merlin"],"ans":1,"exp":"Benar! Dipasangkan dengan satu goal, ia mengubah langkah besok pagi."},{"kind":"close","text":"Satu alat, satu goal, satu langkah besok pagi.","cta":"Buka Goal Saya, lalu Agni Chakti, berdampingan","scene":"stageAgni"}]}$q$),
  ('J-01', $q${"lead":"Tiga goal pagi: ","accent":"kenapa tiga, bukan sepuluh","long":false,"slides":[{"kind":"cover","hook":"Daftar sepuluh tugas membuatmu merasa produktif pada pukul tujuh pagi dan gagal pada pukul sembilan malam.","scene":"tenVsThree"},{"kind":"split","a":"sepuluh10","b":"tiga3"},{"kind":"phone","head":"Tiga yang kamu ingat","text":"Tiga adalah jumlah yang bisa diingat tanpa membuka aplikasi. Tulis goal yang PALING mendekatkanmu ke target hidupmu.","pos":"top","screen":"goals","callout":{"side":"left","top":0.3,"tag":"Goal 2","title":"Jalan 20 menit sebelum makan siang","visual":"check"}},{"kind":"text","head":"Bukan daftar kerja","text":"Goal pagi bukan daftar kerja. Ia pernyataan tentang hari seperti apa yang kamu pilih. Daftar kerja tinggal di tempat lain.","scene":"statementDay"},{"kind":"quiz","q":"Kalau dari tiga goal hanya dua tercapai, itu artinya apa?","opts":["Tetap menang: tiga memang dirancang begitu","Besok tulis lima","Harimu gagal"],"ans":0,"exp":"Benar! Tiga adalah jumlah yang kalau dua tercapai tetap terasa menang."},{"kind":"close","text":"Tiga goal: pernyataan tentang hari seperti apa yang kamu pilih.","cta":"Tulis tiga goalmu","scene":"tenVsThree"}]}$q$),
  ('J-02', $q${"lead":"Satu kemenangan kecil","accent":"sebelum tidur","long":false,"slides":[{"kind":"cover","hook":"Otak tidak menyimpan harimu. Ia menyimpan rangkumannya. Dan rangkuman ditulis sebelum tidur.","scene":"nightSummary"},{"kind":"text","text":"Dalam penelitian yang banyak dikutip, orang yang menuliskan beberapa hal yang ia syukuri tiap malam melaporkan tidur lebih baik dan merasa lebih optimis dalam hitungan minggu, bukan tahun.","scene":"weeksNotYears"},{"kind":"phone","head":"Di Ritual Malam","text":"Setelah mencentang goal, satu pertanyaan: apa yang baik dari hari ini? Satu kalimat cukup. Kalau ingin, tandai dengan ✦ di peta realitasmu.","pos":"bottom","screen":"eveningGoals","callout":{"side":"right","top":0.5,"tag":"Ritual Malam","title":"Apa yang baik dari hari ini?","sub":"✦ bisa ditandai di petamu"}},{"kind":"split","a":"tidakDiakui","b":"ditulis"},{"kind":"quiz","q":"Kenapa satu kemenangan yang ditulis mengalahkan sepuluh yang tidak?","opts":["Karena menulis itu ajaib","Karena yang ditulis adalah yang diingat","Karena sepuluh terlalu banyak"],"ans":1,"exp":"Benar! Bukan karena menulis itu ajaib. Yang ditulis adalah yang diingat."},{"kind":"close","text":"Yang ditulis adalah yang diingat.","cta":"Mulai ritual malam","scene":"nightSummary"}]}$q$),
  ('J-03', $q${"lead":"Yakin dan Nyata: ","accent":"dua angka yang jujur","long":false,"slides":[{"kind":"cover","hook":"Tiap malam kamu diminta dua angka. Keduanya tentang goal yang sama, dari dua sisi yang jarang sepakat.","scene":"twoDials"},{"kind":"phone","head":"Dari dalam, lalu dari luar","text":"Yakin: tanya hatimu, apakah goalmu masih terasa baik dan yakin akan tercapai? Nyata: lihat kenyataan hari ini, uang, tempat, penampilan, situasimu. Seberapa siap dunia nyatamu menyambut goal itu?","pos":"top","screen":"yakinNyata","callout":{"side":"left","top":0.3,"tag":"Dua skala","tagTone":"violet","title":"ragu → yakin penuh","sub":"belum siap → siap menyambut"}},{"kind":"split","a":"yakinTinggi","b":"nyataTinggi"},{"kind":"text","head":"Jaraknya adalah informasi","text":"Yang dibaca Realitas Saya bukan angkanya, melainkan jarak di antara keduanya. Keyakinan yang berlari di depan kenyataan bukan delusi; itu urutan yang wajar. Yang penting kenyataannya menyusul.","scene":"rsBarsBig"},{"kind":"quiz","q":"Apa yang dibaca dari dua angka itu?","opts":["Yang lebih tinggi","Rata-ratanya","Jarak di antara keduanya"],"ans":2,"exp":"Benar! Jaraknya yang bercerita: harapan tanpa langkah, atau langkah tanpa rasa."},{"kind":"close","text":"Dua sisi, satu goal. Jaraknya yang jujur.","cta":"Isi Yakin dan Nyata malam ini","scene":"twoDials"}]}$q$),
  ('J-04', $q${"lead":"Kita adalah","accent":"apa yang kita ulang","long":false,"slides":[{"kind":"cover","hook":"Bukan apa yang kamu putuskan pada tahun baru. Apa yang kamu lakukan pada Selasa biasa.","scene":"tuesday"},{"kind":"list","head":"Tiga waktu dalam sehari","text":"Kartu ritual lama membagi hari menjadi tiga.","rows":[{"color":"#f19e3f","glyph":"sun","name":"Pagi","desc":"Saat bawah sadar paling terbuka. Priming."},{"color":"#413dd9","glyph":"arrow","name":"Siang","desc":"Saat realita dibentuk lewat tindakan biasa."},{"color":"#cb3bed","glyph":"moon","name":"Malam","desc":"Saat hari dinyatakan selesai dan esok diberi kisah baru. Cosmic."}]},{"kind":"split","a":"motivasi","b":"kebiasaan2"},{"kind":"phone","head":"Kartu yang tidak bertanya","text":"Kartu ritual di Home tidak bertanya apakah kamu sedang semangat. Ia hanya ada, tiap pagi dan tiap malam, termasuk Selasa biasa.","pos":"top","screen":"home","callout":{"side":"left","top":0.3,"tag":"Selasa biasa","title":"Ritual Pagi menunggumu"}},{"kind":"quiz","q":"Kebiasaan itu apa?","opts":["Pengganti motivasi saat ia tidak datang","Tanda kurang semangat","Hasil dari motivasi"],"ans":0,"exp":"Benar! Kebiasaan bekerja justru di hari-hari ketika motivasi tidak datang."},{"kind":"close","text":"Hitungannya Selasa-Selasa biasa.","cta":"Lihat streak-mu","scene":"tuesday"}]}$q$),
  ('J-05', $q${"lead":"Menulis rencana besok","accent":"membuat tidur lebih nyenyak","long":true,"slides":[{"kind":"cover","hook":"Pikiran yang berputar di tempat tidur hampir selalu tentang hal yang belum selesai.","scene":"spinningBed"},{"kind":"text","text":"Dalam satu rangkaian penelitian, orang yang menuliskan rencana untuk tugas yang belum selesai lebih jarang diganggu pikiran tentang tugas itu. Bukan menyelesaikannya. Cukup merencanakannya.","scene":"planCard"},{"kind":"quiz","q":"Apa yang membuat otak melepaskan tugas yang menggantung?","opts":["Menyelesaikannya malam itu juga","Yakin tugas itu sudah dipegang: ada rencananya","Melupakannya"],"ans":1,"exp":"Benar! Bukan selesai. Dipegang. Satu kalimat dengan jam sudah cukup."},{"kind":"text","head":"Satu kalimat dengan jam","text":"Otak menagih tugas yang menggantung sampai ia yakin tugas itu sudah dipegang. Kalimat \"besok pukul sembilan aku mengerjakan ini\" cukup untuk membuatnya melepaskan.","scene":"planCard"},{"kind":"phone","head":"Tulis di Ruang Tulis","text":"Tulis di jurnal malam ini, satu kalimat saja, dengan jamnya. Besok pagi ia tinggal jadi goal pertamamu.","pos":"bottom","screen":"ruangTulis","callout":{"side":"right","top":0.46,"tag":"Ruang Tulis","title":"\"Besok pukul sembilan aku…\""}},{"kind":"close","text":"Bukan selesai. Dipegang.","cta":"Tulis jurnal malam ini","scene":"spinningBed"}]}$q$),
  ('J-06', $q${"lead":"Bintang","accent":"di hari yang buruk","long":false,"slides":[{"kind":"cover","hook":"Di peta Realitas Saya ada bintang emas. Ia hanya muncul pada malam yang berat.","scene":"goldStarGrid"},{"kind":"phone","head":"Kamu yang menandainya","text":"Syaratnya satu: kamu menandainya sendiri. Kalau ada yang cukup mengganggumu, tulis apa yang terjadi. Malam itu diberi bintang emas di peta realitasmu.","pos":"top","screen":"painSlide","callout":{"side":"left","top":0.3,"tag":"Ritual Malam","title":"Ada yang berat hari ini?","sub":"Tidak setiap malam ada, dan itu baik."}},{"kind":"text","head":"Pain + Reflection = Progress","text":"Rumus yang diyakini banyak orang sukses. Hari buruk tanpa refleksi hanyalah hari buruk. Hari buruk dengan satu paragraf jujur adalah titik balik.","scene":"formula"},{"kind":"text","text":"Bintang itu bukan hiburan. Ia catatan bahwa kamu tidak membuang rasa sakitnya. Nanti, saat kamu membaca petamu lagi, bintang itulah yang paling banyak bercerita.","scene":"rsMarksBig"},{"kind":"quiz","q":"Dari mana bintang emas itu datang?","opts":["Dari Merlin","Dari angka harimu yang rendah","Dari malam yang kamu tandai sendiri sebagai berat"],"ans":2,"exp":"Benar! Kamu yang menandainya. Tidak ada yang menebak hari beratmu untukmu."},{"kind":"close","text":"Cari bintangmu. Itu titik di mana arah bisa berubah.","cta":"Buka Realitas Saya","scene":"goldStarGrid"}]}$q$),
  ('J-07', $q${"lead":"Satu malam buruk","accent":"bukan arah","long":false,"slides":[{"kind":"cover","hook":"Petamu tidak menilai satu hari. Ia membaca tiga puluh malam. Satu kotak redup di bulan yang terang bukan arah, melainkan ayunan.","scene":"oneDimCell"},{"kind":"phone","head":"Tiga jenis kotak","text":"Terang: malam kamu hadir dan langkahmu dikerjakan. Redup: hadir tanpa langkah. Kosong: tidak hadir. Satu malam tidak mengubah bacaannya.","pos":"bottom","screen":"realitasGrid","callout":{"side":"right","top":0.48,"tag":"30 malam","tagTone":"violet","title":"Satu kotak redup","sub":"ayunan biasa"}},{"kind":"split","a":"panik","b":"siklus"},{"kind":"text","head":"Garis panjangnya","text":"Yang kamu jaga bukan satu malam, melainkan garis tiga puluh malam. Ayunan turun di petamu adalah ayunan biasa; garis panjangnya yang kamu jaga.","scene":"rsGridBig"},{"kind":"quiz","q":"Satu malam yang buruk di peta berarti apa?","opts":["Ayunan biasa; garis tiga puluh malamnya yang dijaga","Mulai ulang dari nol","Arahmu salah"],"ans":0,"exp":"Benar! Investor yang panik menjual di titik terendah. Yang paham siklus menanam."},{"kind":"close","text":"Ayunan biasa. Garis panjangnya yang kamu jaga.","cta":"Lihat tren tujuh hari terakhirmu","scene":"oneDimCell"}]}$q$),
  ('J-08', $q${"lead":"Goal yang","accent":"terbawa ke esok","long":false,"slides":[{"kind":"cover","hook":"Dari tiga goal, biasanya satu atau dua tidak tercentang. Itu normal. Yang penting apa yang terjadi besoknya.","scene":"carryArrow"},{"kind":"phone","head":"Menunggu di pagi berikutnya","text":"Goal yang belum tercapai tidak hilang. Ia menunggumu di check-in pagi berikutnya sebagai usulan. Kamu tinggal mengonfirmasi, mengubah, atau melepaskan.","pos":"top","screen":"goals","callout":{"side":"left","top":0.3,"tag":"dari semalam","title":"Jalan 20 menit sebelum makan siang"}},{"kind":"list","head":"Tiga pilihan tiap pagi","rows":[{"color":"#8fdc9a","glyph":"check","name":"Konfirmasi","desc":"Masih milikmu. Lanjutkan."},{"color":"#413dd9","glyph":"pen","name":"Ubah","desc":"Terlalu besar untuk satu hari? Perkecil."},{"color":"#de4e66","glyph":"x","name":"Lepaskan","desc":"Bukan milikmu. Tidak apa-apa."}]},{"kind":"text","text":"Goal yang terbawa tiga pagi berturut-turut bukan goal yang gagal. Ia goal yang mungkin terlalu besar untuk satu hari, atau sebenarnya bukan milikmu. Keduanya layak ditanyakan.","scene":"threeMornings"},{"kind":"quiz","q":"Goal yang terbawa tiga pagi berturut-turut, artinya?","opts":["Kamu malas","Mungkin terlalu besar, atau bukan milikmu","Harus dipaksa hari ini"],"ans":1,"exp":"Benar! Keduanya layak ditanyakan, bukan dipaksa."},{"kind":"close","text":"Konfirmasi, ubah, atau lepaskan. Tidak ada yang hilang.","cta":"Lihat goal yang terbawa pagi ini","scene":"carryArrow"}]}$q$),
  ('J-09', $q${"lead":"Mimpi setinggi langit,","accent":"goal seukuran hari","long":false,"slides":[{"kind":"cover","hook":"Mimpi dan goal sering ditulis di kolom yang sama. Padahal keduanya bekerja dengan cara berbeda.","scene":"skyDay"},{"kind":"split","a":"mimpi","b":"goal"},{"kind":"text","text":"Mimpi terwujud dari goal-goal kecil yang tercapai, bukan dari mimpi yang ditulis ulang makin besar.","scene":"stairsToCloud"},{"kind":"text","head":"Jangan ada kata tidak","text":"Satu aturan kecil dari kelas lama yang masih berlaku: jangan ada kata \"tidak\" dalam goal. Otak sulit mengejar ketiadaan. \"Tidak terlambat\" kalah oleh \"tiba pukul tujuh\".","scene":"noWord"},{"kind":"quiz","q":"Goal mana yang lebih mudah dikejar otak?","opts":["Keduanya sama","\"Tidak terlambat\"","\"Tiba pukul tujuh\""],"ans":2,"exp":"Benar! Otak sulit mengejar ketiadaan. Beri ia sesuatu untuk dituju."},{"kind":"coba","text":"Periksa tiga goalmu hari ini. Ada kata \"tidak\"? Tulis ulang.","scene":"notebook"},{"kind":"close","text":"Mimpi di langit, goal seukuran hari.","cta":"Buka check-in pagi","scene":"skyDay"}]}$q$),
  ('J-10', $q${"lead":"Jurnal","accent":"tanpa aturan","long":false,"slides":[{"kind":"cover","hook":"Kamu tidak perlu pandai menulis. Kamu perlu jujur selama dua menit.","scene":"twoMinutes"},{"kind":"text","text":"Penelitian tentang menulis bebas tentang pengalaman sendiri sudah berlangsung puluhan tahun. Temuannya konsisten: menuliskan apa yang terjadi dan apa yang dirasakan membantu orang memproses, bukan sekadar mengingat. Tata bahasa tidak dinilai.","scene":"decadesResearch"},{"kind":"phone","head":"Ruang Tulis","text":"Ruang Tulis tidak menilai tata bahasa. Judul boleh kosong. Mulai dari kalimat yang paling gampang.","pos":"bottom","screen":"ruangTulis","callout":{"side":"right","top":0.46,"tag":"Ruang Tulis","title":"Mulai dari kalimat yang paling gampang…"}},{"kind":"phone","head":"Kalau macet, ketuk Pemantik","text":"Pemantik memakai bahanmu sendiri: tag yang kamu tandai hari ini, goal yang kamu tulis, tulisanmu yang lama. Satu ketukan, satu pertanyaan.","pos":"top","screen":"pemantikSheet","callout":{"side":"left","top":0.3,"tag":"Kalau macet","tagTone":"violet","title":"Pemantik","sub":"pertanyaan dari harimu sendiri"}},{"kind":"quiz","q":"Jurnal yang baik itu yang bagaimana?","opts":["Membuatmu berhenti sejenak sebelum kalimat berikutnya","Panjang","Bagus dibaca"],"ans":0,"exp":"Benar! Bukan yang bagus dibaca. Yang membuatmu berhenti sejenak."},{"kind":"close","text":"Jujur dua menit. Tata bahasa tidak dinilai.","cta":"Tulis jurnal malam ini","scene":"twoMinutes"}]}$q$),
  ('J-11', $q${"lead":"Kenapa hari bolos","accent":"tidak dihitung dua kali","long":false,"slides":[{"kind":"cover","hook":"Hari tanpa check-in tidak menjatuhkan petamu. Itu keputusan desain, bukan kelalaian.","scene":"emptyCell"},{"kind":"split","a":"absen","b":"mundur"},{"kind":"text","text":"Streak sudah mencatat ketidakhadiranmu. Kalau peta ikut menghukum, satu hari sakit akan kamu bayar dua kali. Maka kotak kosong tetap kosong: tidak dihitung, tidak dijatuhkan.","scene":"twiceBill"},{"kind":"phone","head":"Yang mencatat absen hanya streak","text":"Dan streak pun bisa dinyalakan kembali. Satu hari terlewat tidak menghapus tiga puluh hari sebelumnya.","pos":"top","screen":"relight","callout":{"side":"left","top":0.3,"tag":"Streak","title":"Nyalakan kembali"}},{"kind":"quiz","q":"Hari tanpa check-in, di peta jadi apa?","opts":["Kotak merah","Kotak kosong: tidak dihitung, tidak dijatuhkan","Mundur satu langkah"],"ans":1,"exp":"Benar! Absen adalah hidup. Hanya mundur yang tercermin di peta."},{"kind":"close","text":"Absen adalah hidup. Mundur adalah hadir tetapi menjauh.","cta":"Nyalakan kembali streak-mu, kalau sedang padam","scene":"emptyCell"}]}$q$),
  ('J-12', $q${"lead":"Tiga puluh malam biasa","accent":"yang menggerakkan posisimu","long":true,"slides":[{"kind":"cover","hook":"Posisimu di garis Stage 1 ke 3 tidak digerakkan oleh satu malam hebat. Ia digerakkan tiga puluh malam biasa yang kamu tetap hadir.","scene":"thirtyNights"},{"kind":"phone","head":"Angka yang menghitung tiga puluh hari","text":"Angka besar di Realitas Saya menghitung tiga puluh hari terakhir: langkah yang kamu tulis sendiri dan benar-benar kamu kerjakan, malam-malam kamu hadir. Bukan satu hari hebat.","pos":"top","screen":"realitas","callout":{"side":"left","top":0.3,"tag":"30 hari","tagTone":"violet","title":"14 dari 21 langkah","sub":"18 malam hadir dari 30"}},{"kind":"split","a":"begadang","b":"biasa"},{"kind":"text","text":"Itulah momentum: gerak yang terasa ringan karena tidak pernah berhenti. Ia dibangun dari hari-hari yang tidak istimewa, yang kamu tetap hadir.","scene":"rollingBall"},{"kind":"quiz","q":"Apa yang menggerakkan posisimu di garis Stage?","opts":["Membaca artikel ini","Satu malam penuh semangat","Tiga puluh malam biasa yang kamu tetap hadir"],"ans":2,"exp":"Benar! Posisi tidak bisa dibeli dengan satu malam begadang. Ia dibangun dari hari-hari biasa."},{"kind":"close","text":"Gerak yang ringan karena tidak pernah berhenti.","cta":"Buka Realitas Saya","scene":"thirtyNights"}]}$q$),
  ('A-01', $q${"lead":"Mandi","accent":"untuk pikiran","long":false,"slides":[{"kind":"cover","hook":"Kamu mandi setiap hari tanpa bertanya \"apakah mandi itu bekerja?\".","scene":"shower"},{"kind":"text","text":"Pikiran menerima ribuan masukan sehari: pesan, berita, komentar, kekhawatiran orang lain. Tidak ada yang membersihkannya. Sesi audio sepuluh menit adalah mandi untuk bagian dirimu yang tidak bisa disabuni.","scene":"shower"},{"kind":"split","a":"mengosongkan","b":"membilas"},{"kind":"phone","head":"Tiga pintu, tiga jam","text":"Priming di pagi hari, Ignite di tengah hari, Cosmic sebelum tidur. Semuanya di Home, sesuai jamnya.","pos":"top","screen":"igniteSelect","callout":{"side":"left","top":0.3,"tag":"Tengah hari","title":"CALM","sub":"Untuk pikiran yang penuh."}},{"kind":"quiz","q":"Meditasi di sini tentang apa?","opts":["Membilas, supaya yang tersisa milikmu sendiri","Berhenti berpikir","Mengosongkan pikiran"],"ans":0,"exp":"Benar! Pikiran tidak bisa kosong. Ia bisa dibilas."},{"kind":"close","text":"Mandi untuk bagian dirimu yang tidak bisa disabuni.","cta":"Pilih satu sesi: Priming, Ignite, atau Cosmic","scene":"threeDoorsTime"}]}$q$),
  ('A-02', $q${"lead":"Pikiranmu melantur","accent":"hampir separuh waktu","long":true,"slides":[{"kind":"cover","hook":"Dua peneliti mengirim pertanyaan acak ke ribuan ponsel: \"sedang apa, dan sedang memikirkan apa?\"","scene":"wander47"},{"kind":"quiz","q":"Berapa sering orang memikirkan hal lain dari yang sedang ia kerjakan?","opts":["Sekitar 10 persen waktu","Sekitar 47 persen waktu","Hampir tidak pernah"],"ans":1,"exp":"Benar! Hampir separuh waktu. Dan saat melantur, orang melaporkan diri kurang bahagia, apa pun kegiatannya."},{"kind":"text","text":"Masalahnya bukan hidupmu. Masalahnya kamu jarang hadir di dalamnya.","scene":"wander47"},{"kind":"phone","head":"Latihan kembali","text":"Sesi audio adalah latihan kembali, berulang-ulang, sampai kembali itu menjadi refleks. CALM tiga menit sudah cukup untuk satu putaran.","pos":"bottom","screen":"calm","callout":{"side":"right","top":0.46,"tag":"3 menit","title":"CALM","sub":"satu putaran kembali"}},{"kind":"close","text":"Bukan hidupmu yang salah. Kamu jarang hadir di dalamnya.","cta":"Mulai CALM, tiga menit","scene":"guideVoice"}]}$q$),
  ('A-03', $q${"lead":"Delapan minggu","accent":"yang mengubah otak","long":false,"slides":[{"kind":"cover","hook":"Sebelum 2011, \"meditasi mengubah otak\" adalah klaim. Setelah itu, ia foto.","scene":"brainScan"},{"kind":"text","text":"Peserta berlatih sekitar 27 menit sehari selama delapan minggu. Pemindaian menunjukkan penebalan di wilayah yang mengurus belajar dan ingatan, dan penyusutan di wilayah yang mengurus rasa takut dan stres.","scene":"brainScan"},{"kind":"text","head":"Kenapa delapan minggu","text":"Delapan minggu bukan angka ajaib. Ia angka yang cukup lama untuk tubuh percaya bahwa kamu serius.","scene":"calendar"},{"kind":"quiz","q":"Apa arti delapan minggu di sini?","opts":["Batas maksimal berlatih","Angka ajaib dari penelitian","Cukup lama untuk tubuh percaya kamu serius"],"ans":2,"exp":"Benar! Bukan ajaib. Cukup lama untuk dipercaya tubuhmu."},{"kind":"text","text":"Delapan minggu adalah 56 hari. Streak-mu menghitungnya untukmu, satu malam demi satu malam.","scene":"streakRow"},{"kind":"close","text":"Delapan minggu. 56 hari. Satu demi satu.","cta":"Lihat streak-mu","scene":"streakRow"}]}$q$),
  ('A-04', $q${"lead":"Neurons that fire together","accent":"wire together","long":true,"slides":[{"kind":"cover","hook":"Kalimat ini diajarkan di kelas ilmu saraf mana pun. Ia juga menjelaskan kenapa ritual pagi diulang setiap hari.","scene":"wiresTogether"},{"kind":"text","text":"Setiap kali dua hal terjadi bersamaan di otak, jalur di antara keduanya menguat. Perasaan tenang yang diulang bersama tiga goalmu, setiap pagi, lama-lama menjadi satu paket: melihat goal, langsung tenang.","scene":"wiresTogether"},{"kind":"phone","head":"Pagi yang sama, tiap hari","text":"Check-in satu menit, lalu meditasi Priming. Urutan yang sama tiap pagi, supaya kabelnya terpasang.","pos":"bottom","screen":"primingPage","callout":{"side":"right","top":0.48,"tag":"Tiap pagi","title":"Check-in, lalu PRIMING"}},{"kind":"text","head":"Memasang kabel","text":"Kamu tidak sedang memaksakan pikiran positif. Kamu sedang memasang kabel. Kabel tidak peduli motivasi; ia peduli pengulangan.","scene":"wiresTogether"},{"kind":"quiz","q":"Apa yang dipedulikan \"kabel\" di otakmu?","opts":["Pengulangan","Pikiran positif","Motivasi"],"ans":0,"exp":"Benar! Kabel tidak peduli motivasi. Ia peduli pengulangan."},{"kind":"close","text":"Bukan memaksa pikiran positif. Memasang kabel.","cta":"Mulai Priming besok pagi, sebelum membuka pesan","scene":"wiresTogether"}]}$q$),
  ('A-05', $q${"lead":"Masukan pertama","accent":"di pagi hari","long":false,"slides":[{"kind":"cover","hook":"Apa hal pertama yang masuk ke kepalamu pagi ini? Kalau jawabannya \"notifikasi\", kamu sudah kalah satu langkah.","scene":"firstInput"},{"kind":"text","text":"Dalam psikologi, apa yang kamu terima lebih dulu memengaruhi cara kamu menafsirkan yang datang setelahnya. Karena itu Priming diminta dilakukan sebelum mengecek ponsel, sebelum bicara dengan siapa pun.","scene":"firstInput"},{"kind":"split","a":"notifikasi","b":"primingDulu"},{"kind":"quiz","q":"Kenapa Priming sebaiknya sebelum membuka pesan?","opts":["Supaya pesannya tidak terlewat","Karena masukan pertama menafsirkan yang datang setelahnya","Karena pagi lebih sepi"],"ans":1,"exp":"Benar! Pagi hari ada satu kursi kosong di kepalamu. Kalau kamu tidak mendudukinya, orang lain yang akan."},{"kind":"phone","head":"Pengingat sebelum alarm pesan","text":"Atur pengingat Priming lebih awal dari jam pesanmu biasanya masuk. Kursinya kamu duduki lebih dulu.","pos":"top","screen":"notif","callout":{"side":"left","top":0.3,"tag":"Lebih awal","title":"Pengingat Priming"}},{"kind":"close","text":"Satu kursi kosong tiap pagi. Dudukilah lebih dulu.","cta":"Atur pengingat Priming lebih awal dari alarm pesanmu","scene":"firstInput"}]}$q$),
  ('A-06', $q${"lead":"Napas 8-8-8-8: ","accent":"tombol rem tubuhmu","long":false,"slides":[{"kind":"cover","hook":"Pasukan khusus memakai hitungan empat. Modwiz memakai delapan. Keduanya menekan tombol yang sama.","scene":"breath8"},{"kind":"text","text":"Tarik delapan hitungan, tahan delapan, buang delapan, kosong delapan. Embusan panjang memberi sinyal pada sistem sarafmu bahwa tidak ada bahaya. Detak melambat, bahu turun, pikiran ikut.","scene":"breath8"},{"kind":"phone","head":"Dipandu di dalam sesi","text":"Pemutar sesi menampilkan fase napasmu dan hitungannya. Kamu tinggal mengikuti bola.","pos":"bottom","screen":"player","callout":{"side":"right","top":0.5,"tag":"INHALE · 8","title":"Ikuti bolanya"}},{"kind":"text","text":"Kamu tidak bisa memerintahkan diri untuk tenang. Tetapi kamu bisa memerintahkan napas, dan tubuh akan menyusul.","scene":"breath8"},{"kind":"coba","text":"Lakukan sekarang, tiga putaran, sebelum lanjut membaca.","scene":"breath8"},{"kind":"close","text":"Perintahkan napasnya. Tubuh menyusul.","cta":"Mulai Priming","scene":"breath8"}]}$q$),
  ('A-07', $q${"lead":"Kenapa dipandu,","accent":"bukan hening","long":false,"slides":[{"kind":"cover","hook":"Meditasi hening sering gagal di menit kedua. Bukan karena kamu tidak berbakat.","scene":"guideVoice"},{"kind":"split","a":"hening","b":"dipandu"},{"kind":"text","text":"Pikiran yang tidak diberi pegangan akan melantur, dan pemula akan menganggap itu kegagalan lalu berhenti. Suara pemandu adalah pegangan: tiap kali kamu lepas, ada kalimat berikutnya yang mengembalikanmu.","scene":"guideVoice"},{"kind":"quiz","q":"\"Kembali\" setelah melantur itu apa?","opts":["Latihannya itu sendiri","Tanda butuh sesi lebih panjang","Tanda gagal"],"ans":0,"exp":"Benar! Dipandu bukan tingkat pemula. Ia cara memastikan kamu kembali, berkali-kali."},{"kind":"close","text":"Kembali, berkali-kali. Itulah latihannya.","cta":"Pilih sesi dengan pemandu suara","scene":"guideVoice"}]}$q$),
  ('A-08', $q${"lead":"Tiga ritual,","accent":"tiga pintu","long":false,"slides":[{"kind":"cover","hook":"Kenapa tidak satu sesi saja? Karena pagi, siang, dan malam adalah tiga keadaan tubuh yang berbeda.","scene":"threeDoorsTime"},{"kind":"list","head":"Tiga pintu","rows":[{"color":"#f19e3f","glyph":"sun","name":"Pagi · PRIMING","desc":"Bawah sadar paling terbuka. Saat yang tepat menanam arah."},{"color":"#de4e66","glyph":"zap","name":"Siang · IGNITE","desc":"CREATE untuk membuka ide, CALM untuk meredam, READY untuk bersiap."},{"color":"#cb3bed","glyph":"moon","name":"Malam · COSMIC","desc":"Menutup hari dengan syukur sebelum otak merangkum."}]},{"kind":"phone","head":"Tiga arah di tengah hari","text":"Ignite menanyakan satu hal: arah mana yang paling kamu butuhkan sekarang? Buntu, penuh, atau perlu berani.","pos":"top","screen":"igniteSelect","callout":{"side":"left","top":0.3,"tag":"Pilih arah","title":"CREATE · CALM · READY"}},{"kind":"quiz","q":"Sesi yang tepat pada jam yang salah terasa seperti apa?","opts":["Olahraga ringan","Obat yang diminum tanpa makan","Tidur siang"],"ans":1,"exp":"Benar! Pilih pintunya sesuai jamnya."},{"kind":"close","text":"Pilih pintunya sesuai jamnya.","cta":"Lihat ritual yang sedang menunggumu di Home","scene":"threeDoorsTime"}]}$q$),
  ('A-09', $q${"lead":"Syukur sebelum tidur mengubah","accent":"apa yang otakmu simpan","long":true,"slides":[{"kind":"cover","hook":"Tidur bukan jeda. Tidur adalah saat otak memutuskan apa dari hari ini yang layak disimpan.","scene":"sleepSort"},{"kind":"text","text":"Ingatan dirapikan saat kamu tidur. Yang kamu pikirkan menjelang tidur mendapat tempat lebih depan dalam antrean. Sesi Cosmic sengaja ditaruh di ujung hari karena itu.","scene":"sleepSort"},{"kind":"phone","head":"GRATITUDE, di ujung hari","text":"Meditasi Cosmic pertama bernama GRATITUDE: syukur, lalu turun pelan-pelan ke tidur. Dibuka sekali dengan 5 Souls.","pos":"bottom","screen":"cosmicPage","callout":{"side":"right","top":0.5,"tag":"Cosmic","title":"Gratitude → Wind Down"}},{"kind":"quiz","q":"Kenapa Cosmic ditaruh di ujung hari?","opts":["Karena malam lebih tenang","Supaya cepat tidur","Karena yang dipikirkan menjelang tidur disimpan lebih depan"],"ans":2,"exp":"Benar! Ingatan dirapikan saat tidur. Yang kamu bawa tidur, itu yang disimpan."},{"kind":"close","text":"Kamu tidak memilih apa yang terjadi. Kamu memilih versi mana yang dibawa tidur.","cta":"Mulai Cosmic malam ini","scene":"sleepSort"}]}$q$),
  ('A-10', $q${"lead":"Sepuluh menit tiap hari mengalahkan","accent":"satu jam sesekali","long":true,"slides":[{"kind":"cover","hook":"Satu jam hening pada hari Minggu terasa hebat. Senin pagi, efeknya sudah tidak ada.","scene":"calendar"},{"kind":"text","text":"Tubuh dan otak merespons frekuensi, bukan durasi.","scene":"pulse"},{"kind":"split","a":"sekali","b":"tiap"},{"kind":"quiz","q":"Menurut artikel ini, tubuh dan otak lebih merespons apa?","opts":["Frekuensi: makin sering makin baik","Suasana tempatnya","Durasi: makin lama makin baik"],"ans":0,"exp":"Benar! Sepuluh menit yang datang tiap hari memberi sinyal \"ini keadaan normal baru\"."},{"kind":"text","text":"Pertanyaannya bukan berapa lama kamu bermeditasi. Pertanyaannya berapa hari berturut-turut.","scene":"streakRow"},{"kind":"close","text":"Bukan berapa lama. Berapa hari berturut-turut.","cta":"Lihat streak-mu","scene":"streakRow"}]}$q$),
  ('A-11', $q${"lead":"Awesome Priming: kenapa pemilik gelang","accent":"menyebutnya \"pengaktifan\"","long":true,"slides":[{"kind":"cover","hook":"Ada satu sesi di aplikasi ini yang tertutup untuk umum. Peserta kelasnya punya nama sendiri untuk pengalaman pertama mereka.","scene":"pendantThumb"},{"kind":"list","head":"Yang terjadi di dalamnya","text":"Enam belas menit, dipandu suara, batu per batu.","rows":[{"color":"#f19e3f","glyph":"sun","name":"Jempol di liontin","desc":"Tiga kalimat pembuka."},{"color":"#5AC8FA","glyph":"refresh","name":"Napas delapan hitungan","desc":"Tombol rem tubuh."},{"color":"#cb3bed","glyph":"eye","name":"Menyelami tiga realita","desc":"Dibayangkan sampai terasa nyata."}]},{"kind":"phone","head":"Tertutup untuk umum","text":"AWESOME PRIMING ada di halaman Priming, tetapi hanya terbuka untuk pemilik Awesome Bracelet yang terdaftar di kelasnya.","pos":"bottom","screen":"primingPage","callout":{"side":"right","top":0.54,"tag":"AB OWNER ONLY","title":"Awesome Priming · 16 menit"}},{"kind":"text","text":"Banyak yang, setelah sesi pertama, langsung menulis ke grup. Bukan diminta. Karena ada yang terasa berpindah.","scene":"groupMessages"},{"kind":"quiz","q":"Dari mana kata \"pengaktifan\" datang?","opts":["Dari nama resmi kelasnya","Dari orang-orang yang merasakannya","Dari Merlin"],"ans":1,"exp":"Benar! Bukan dibuat oleh kami. Lahir dari yang merasakannya."},{"kind":"close","text":"Rasa, bukan penjelasan, yang membuat seseorang kembali esok paginya.","cta":"Lihat Awesome Bracelet di Courses","scene":"pendantThumb"}]}$q$),
  ('A-12', $q${"lead":"Membayangkan tiga realita","accent":"bukan khayalan, melainkan latihan","long":true,"slides":[{"kind":"cover","hook":"Atlet lompat ski melompat puluhan kali di kepalanya sebelum sekali di salju. Mereka tidak menyebutnya berkhayal.","scene":"skiJumper"},{"kind":"text","text":"Latihan mental dipakai luas dalam olahraga karena otak mengaktifkan sebagian jalur yang sama saat membayangkan gerakan dengan saat melakukannya. Priming bekerja dengan prinsip yang sama: membayangkan keberhasilanmu sampai terasa, dan di Awesome Priming, menyelami tiga realita yang ingin kamu miliki.","scene":"skiJumper"},{"kind":"split","a":"khayalan","b":"latihan"},{"kind":"quiz","q":"Apa yang membedakan latihan mental dari khayalan?","opts":["Lamanya membayangkan","Seberapa jelas bayangannya","Diulang pada jam yang sama dan diikuti tindakan nyata"],"ans":2,"exp":"Benar! Tanpa tindakan di siang hari, ia tinggal khayalan. Dengan tindakan, ia gladi bersih."},{"kind":"text","text":"Bedanya khayalan dan latihan ada di dua hal: diulang pada jam yang sama, dan diikuti tindakan nyata di siang hari. Tanpa yang kedua, ia tinggal khayalan. Dengan yang kedua, ia gladi bersih.","scene":"rehearsal"},{"kind":"close","text":"Bayangkan pagi ini. Lakukan siang ini.","cta":"Mulai Priming, lalu tulis tiga goal yang menyusul bayanganmu","scene":"rehearsal"}]}$q$)
) as v(id, slides) where a.id = v.id;
